-- AC335 data: supplied archive + pinned AzerothCore source; no MoP world rows.
AzerothAdminAC335=AzerothAdminAC335 or {}
AzerothAdminAC335.ServerCommandIndex={{["name"]="account",["help"]="Syntax: .account\r\n\r\nDisplay the access level of your account and the email adress if you possess the necessary permissions.",["security"]=0,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT"},{["name"]="account 2fa",["help"]="Syntax: .account 2fa <setup/remove>\n\nSet up or remove two-factor authentication (TOTP) for this account.",["security"]=0,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]=""},{["name"]="account 2fa remove",["help"]="Syntax: .account 2fa remove <token>\nDisables two-factor authentication for this account, if enabled.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="account 2fa setup",["help"]="Syntax: .account 2fa setup\nSets up two-factor authentication for this account.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="account addon",["help"]="Syntax: .account addon #addon\nSet expansion addon level allowed. Addon values: 0 - normal, 1 - tbc, 2 - wotlk.",["security"]=1,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_ADDON"},{["name"]="account create",["help"]="Syntax: .account create $account $password $email\r\n\r\nCreate account and set password to it.\r\n$email is optional, can be left blank.",["security"]=4,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_CREATE"},{["name"]="account delete",["help"]="Syntax: .account delete $account\r\n\r\nDelete account with all characters.",["security"]=4,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_DELETE"},{["name"]="account lock country",["help"]="Syntax: .account lock country [on|off]\nAllow login from account only from current used Country or remove this requirement.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="account lock ip",["help"]="Syntax: .account lock ip [on|off]\nAllow login from account only from current used IP or remove this requirement.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="account onlinelist",["help"]="Syntax: .account onlinelist\r\n\r\nShow list of online accounts.",["security"]=4,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_ONLINE_LIST"},{["name"]="account password",["help"]="Syntax: .account password $old_password $new_password $new_password [$email]\r\n\r\nChange your account password. You may need to check the actual security mode to see if email input is necessary.",["security"]=0,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_PASSWORD"},{["name"]="account remove country",["help"]="Syntax: .account remove country <account>\n\nRemoves the country information associated with the specified account.",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="account set",["help"]="Syntax: .account set $subcommand\nType .account set to see the list of possible subcommands or .help account set $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="account set 2fa",["help"]="Syntax: .account set 2fa <account> <secret/off>\nProvide a base32 encoded secret to setup two-factor authentication for the account.\nSpecify 'off' to disable two-factor authentication for the account.",["security"]=0,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_SET"},{["name"]="account set addon",["help"]="Syntax: .account set addon [$account] #addon\r\n\r\nSet user (possible targeted) expansion addon level allowed. Addon values: 0 - normal, 1 - tbc, 2 - wotlk.",["security"]=2,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_SET_ADDON"},{["name"]="account set email",["help"]="Syntax: .account set email $account $email $email_confirmation\nAdd or change an email to the account.",["security"]=3,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_SET_SEC_EMAIL"},{["name"]="account set gmlevel",["help"]="Syntax: .account set gmlevel [$account] #level [#realmid]\r\n\r\nSet the security level for targeted player (can't be used at self) or for account $name to a level of #level on the realm #realmID.\r\n\r\n#level may range from 0 to 3.\r\n\r\n#reamID may be -1 for all realms.",["security"]=3,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_SET_SECLEVEL"},{["name"]="account set password",["help"]="Syntax: .account set password $account $password $password\r\n\r\nSet password for account.",["security"]=3,["source"]="cs_account.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACCOUNT_SET_PASSWORD"},{["name"]="achievement",["help"]="Syntax: .achievement $subcommand\nType .achievement to see the list of possible subcommands or .help achievement $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="achievement add",["help"]="Syntax: .achievement add $achievement\nAdd an achievement to the targeted player.\n$achievement: can be either achievement id or achievement link",["security"]=2,["source"]="cs_achievement.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACHIEVEMENT_ADD"},{["name"]="achievement checkall",["help"]="Syntax: .achievement checkall\r\nCheck all achievement criteria of the selected player.",["security"]=3,["source"]="cs_achievement.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ACHIEVEMENT_CHECKALL"},{["name"]="additem",["help"]="Syntax: .additem Optional(playerName/playerGUID) #itemID/[#itemName]/#itemLink #itemCount\r\nAdds the specified item to you, the selected character or the specifed character name/GUID.\r\nIf #itemCount is negative, you will remove #itemID.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ADDITEM"},{["name"]="additem set",["help"]="Syntax: .additemset #itemsetid\r\n\r\nAdd items from itemset of id #itemsetid to your or selected character inventory. Will add by one example each item from itemset.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ADDITEMSET"},{["name"]="announce",["help"]="Syntax: .announce $MessageToBroadcast\r\n\r\nSend a global message to all players online in chat log.",["security"]=2,["source"]="cs_message.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ANNOUNCE"},{["name"]="appear",["help"]="Syntax: .appear [$charactername]\r\n\r\nTeleport to the given character. Either specify the character name or click on the character's portrait,e.g. when you are in a group. Character can be offline.",["security"]=1,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_APPEAR"},{["name"]="arena captain",["help"]="Syntax: .arena captain #TeamID $name\n\nA command to set new captain to the team $name must be in the team",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_CAPTAIN"},{["name"]="arena create",["help"]="Syntax: .arena create $name \"arena name\" #type\n\nA command to create a new Arena-team in game. #type  = [2/3/5]",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_CREATE"},{["name"]="arena disband",["help"]="Syntax: .arena disband #TeamID\n\nA command to disband Arena-team in game.",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_DISBAND"},{["name"]="arena info",["help"]="Syntax: .arena info #TeamID\n\nA command that show info about arena team",["security"]=2,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_INFO"},{["name"]="arena lookup",["help"]="Syntax: .arena lookup $name\n\nA command that give a list of arenateam with the given $name",["security"]=2,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_LOOKUP"},{["name"]="arena rename",["help"]="Syntax: .arena rename \"oldname\" \"newname\"\n\nA command to rename Arena-team name.",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_RENAME"},{["name"]="arena season deleteteams",["help"]="Syntax: .arena season deleteteams\nDeletes ALL arena teams.",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_SEASON_DELETETEAMS"},{["name"]="arena season reward",["help"]="Syntax: .arena season reward $brackets\nBuilds a ladder by combining team brackets and provides rewards from the arena_season_reward table.\nExample usage:\n \n# Combine all brackets, build a ladder, and distribute rewards among them\n.arena season reward all\n \n# Build ladders separately for 2v2, 3v3, and 5v5 brackets so each bracket receives its own rewards\n.arena season reward 2\n.arena season reward 3\n.arena season reward 5\n \n# Combine 2v2 and 3v3 brackets and distribute rewards\n.arena season reward 2,3",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_SEASON_REWARD"},{["name"]="arena season set state",["help"]="Syntax: .arena season set state $state\nChanges the state for the current season.\nAvailable states:\n 0 - disabled. Players can't queue for the arena.\n 1 - in progress. Players can use arena-related functionality.",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_SEASON"},{["name"]="arena season start",["help"]="Syntax: .arena season start $season_id\nStarts a new arena season, places the correct vendors, and sets the new season state to IN PROGRESS.",["security"]=3,["source"]="cs_arena.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ARENA_SEASON_START"},{["name"]="aura",["help"]="Syntax: .aura #spellid\r\n\r\nAdd the aura from spell #spellid to the selected Unit.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_AURA"},{["name"]="aura stack",["help"]="Syntax: .aurastack #spellid #stacks\r\n\r\nModify #stacks of an already applied #spellid to the selected Unit.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_AURA_STACK"},{["name"]="autobroadcast",["help"]="Syntax: .autobroadcast $subcommand\nType .autobroadcast to see a list of subcommands or .help autobroadcast $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="autobroadcast add",["help"]="Syntax: .autobroadcast add $weight $text\nAdd a new autobroadcast entry with the given weight and text.",["security"]=3,["source"]="cs_autobroadcast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_AUTOBROADCAST_ADD"},{["name"]="autobroadcast list",["help"]="Syntax: .autobroadcast list\nList all autobroadcast entries.",["security"]=2,["source"]="cs_autobroadcast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_AUTOBROADCAST_LIST"},{["name"]="autobroadcast locale",["help"]="Syntax: .autobroadcast locale $id $locale $text\nAdd or replace a localized text for the autobroadcast entry with the given ID.",["security"]=3,["source"]="cs_autobroadcast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_AUTOBROADCAST_LOCALE"},{["name"]="autobroadcast remove",["help"]="Syntax: .autobroadcast remove $id\nRemove the autobroadcast entry with the given ID and its locale entries.",["security"]=3,["source"]="cs_autobroadcast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_AUTOBROADCAST_REMOVE"},{["name"]="bags",["help"]="Syntax: .bags $subcommand \nType .bags to see the list of possible subcommands or .help bags $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="bags clear",["help"]="Syntax: .bags clear $itemQuality \nClear from players' bags all items including and below $itemQuality (or all items if used .bags clear all).",["security"]=2,["source"]="cs_bag.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ADDITEM"},{["name"]="ban",["help"]="Syntax: .ban $subcommand\nType .ban to see the list of possible subcommands or .help ban $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="ban account",["help"]="Syntax: .ban account $Name $bantime $reason\r\nBan account kick player.\r\n$bantime: negative value leads to permban, otherwise use a timestring like \"4d20h3s\".",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BAN_ACCOUNT"},{["name"]="ban character",["help"]="Syntax: .ban character $Name $bantime $reason\nBan character and kick player.\n$bantime: negative value leads to permban, otherwise use a timestring like \"4d20h3s\".",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BAN_CHARACTER"},{["name"]="ban ip",["help"]="Syntax: .ban ip $Ip $bantime $reason\r\nBan IP.\r\n$bantime: negative value leads to permban, otherwise use a timestring like \"4d20h3s\".",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BAN_IP"},{["name"]="ban playeraccount",["help"]="Syntax: .ban playeraccount $Name $bantime $reason\nBan account and kick player.\n$bantime: negative value leads to permban, otherwise use a timestring like \"4d20h3s\".",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BAN_PLAYERACCOUNT"},{["name"]="baninfo",["help"]="Syntax: .baninfo $subcommand\nType .baninfo to see the list of possible subcommands or .help baninfo $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="baninfo account",["help"]="Syntax: .baninfo account $accountid\r\nWatch full information about a specific ban.",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BANINFO_ACCOUNT"},{["name"]="baninfo character",["help"]="Syntax: .baninfo character $charactername \r\nWatch full information about a specific ban.",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BANINFO_CHARACTER"},{["name"]="baninfo ip",["help"]="Syntax: .baninfo ip $ip\r\nWatch full information about a specific ban.",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BANINFO_IP"},{["name"]="banlist",["help"]="Syntax: .banlist $subcommand\nType .banlist to see the list of possible subcommands or .help banlist $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="banlist account",["help"]="Syntax: .banlist account [$Name]\r\nSearches the banlist for a account name pattern or show full list account bans.",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BANLIST_ACCOUNT"},{["name"]="banlist character",["help"]="Syntax: .banlist character $Name\r\nSearches the banlist for a character name pattern. Pattern required.",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BANLIST_CHARACTER"},{["name"]="banlist ip",["help"]="Syntax: .banlist ip [$Ip]\r\nSearches the banlist for a IP pattern or show full list of IP bans.",["security"]=2,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BANLIST_IP"},{["name"]="bf",["help"]="Syntax: .bf $subcommand\nType .bf to see the list of possible subcommands or .help bf $subcommand to see info on subcommands.",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="bf enable",["help"]="Syntax: .bf enable <battleid>\n\nEnable a battlefield (e.g. Wintergrasp) by its battle id.",["security"]=3,["source"]="cs_bf.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BF_ENABLE"},{["name"]="bf queue",["help"]="Syntax: .bf queue #battleid\r\nDisplays all players currently in queue, invited, or actively in war for the specified battlefield.\r\n#battleid: the battle ID (e.g. 1 for Wintergrasp).",["security"]=2,["source"]="cs_bf.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BF_QUEUE"},{["name"]="bf start",["help"]="Syntax: .bf start <battleid>\n\nForce the battlefield with the given battle id to start now.",["security"]=3,["source"]="cs_bf.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BF_START"},{["name"]="bf stop",["help"]="Syntax: .bf stop <battleid>\n\nForce the battlefield with the given battle id to end now.",["security"]=3,["source"]="cs_bf.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BF_STOP"},{["name"]="bf switch",["help"]="Syntax: .bf switch <battleid>\n\nSwitch the controlling/defending team of the given battlefield.",["security"]=3,["source"]="cs_bf.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BF_SWITCH"},{["name"]="bf timer",["help"]="Syntax: .bf timer #battleid #timer\n#timer: use a timestring like \"1h15m30s\".",["security"]=3,["source"]="cs_bf.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BF_TIMER"},{["name"]="bindsight",["help"]="Syntax: .bindsight\r\n\r\nBinds vision to the selected unit indefinitely. Cannot be used while currently possessing a target.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BINDSIGHT"},{["name"]="bm",["help"]="Syntax: .bm [on/off]\nEnable or Disable in game Beastmaster mode or show current state if on/off not provided.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_BEASTMASTER"},{["name"]="cache",["help"]="Character data cached during start up.\nType .cache to see a list of subcommands or .help $subcommand to see info on subcommands.",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="cache delete",["help"]="Syntax: .cache delete $playerName\nDeletes the cached data for the selected character. Use for debugging only!",["security"]=3,["source"]="cs_cache.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="cache info",["help"]="Syntax: .cache info $playerName\nDisplays cached data for the selected character.",["security"]=2,["source"]="cs_cache.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="cache refresh",["help"]="Syntax: .cache refresh $playerName\nDeletes the current cache and refreshes it with updated data.",["security"]=2,["source"]="cs_cache.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="cast",["help"]="Syntax: .cast #spellid [triggered]\r\n  Cast #spellid to selected target. If no target selected cast to self. If 'triggered' or part provided then spell cast with triggered flag.",["security"]=2,["source"]="cs_cast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CAST"},{["name"]="cast back",["help"]="Syntax: .cast back #spellid [triggered]\r\n  Selected target will cast #spellid to your character. If 'triggered' or part provided then spell cast with triggered flag.",["security"]=2,["source"]="cs_cast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CAST_BACK"},{["name"]="cast dest",["help"]="Syntax: .cast dest #spellid #x #y #z [triggered]\r\n  Selected target will cast #spellid at provided destination. If 'triggered' or part provided then spell cast with triggered flag.",["security"]=2,["source"]="cs_cast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CAST_DEST"},{["name"]="cast dist",["help"]="Syntax: .cast dist #spellid [#dist [triggered]]\r\n  You will cast spell to point at distance #dist. If 'triggered' or part provided then spell cast with triggered flag. Not all spells can be cast as area spells.",["security"]=2,["source"]="cs_cast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CAST_DIST"},{["name"]="cast self",["help"]="Syntax: .cast self #spellid [triggered]\r\n  Cast #spellid by target at target itself. If 'triggered' or part provided then spell cast with triggered flag.",["security"]=2,["source"]="cs_cast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CAST_SELF"},{["name"]="cast target",["help"]="Syntax: .cast target #spellid [triggered]\r\n  Selected target will cast #spellid to his victim. If 'triggered' or part provided then spell cast with triggered flag.",["security"]=2,["source"]="cs_cast.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CAST_TARGET"},{["name"]="character",["help"]="Syntax: character $subcommand\n Type .character to see a list of possible subcommands\n or .help character $subcommand to see info on the subcommand.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="character changeaccount",["help"]="Syntax: .character changeaccount $NewAccountName $Name.\nMoves the specified character to the provided account. \nKicks the player if the character is online.",["security"]=3,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_CHANGEACCOUNT"},{["name"]="character changefaction",["help"]="Syntax: .character changefaction $name\r\n\r\nChange character faction.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_CHANGEFACTION"},{["name"]="character changerace",["help"]="Syntax: .character changerace $name\r\n\r\nChange character race.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_CHANGERACE"},{["name"]="character check bag",["help"]="Syntax: .character check bag [<target_player>] <bagSlot 1-4>\n\nList the contents of the target player bag in the given slot (1-4).",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_CHECK_BAG"},{["name"]="character check bank",["help"]="Syntax: .character check bank \r\n\r\nShow your bank inventory.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_CHECK_BANK"},{["name"]="character check profession",["help"]="Syntax: .character check profession [$target_player]\r\nShow known professions list for selected player",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_CHECK_PROFESSION"},{["name"]="character customize",["help"]="Syntax: .character customize [$name]\r\n\r\nMark selected in game or by $name in command character for customize at next login.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_CUSTOMIZE"},{["name"]="character deleted delete",["help"]="Syntax: .character deleted delete #guid|$name\r\n\r\nCompletely deletes the selected characters.\r\nIf $name is supplied, only characters with that string in their name will be deleted, if #guid is supplied, only the character with that GUID will be deleted.",["security"]=4,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_DELETED_DELETE"},{["name"]="character deleted list",["help"]="Syntax: .character deleted list [#guid|$name]\r\n\r\nShows a list with all deleted characters.\r\nIf $name is supplied, only characters with that string in their name will be selected, if #guid is supplied, only the character with that GUID will be selected.",["security"]=3,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_DELETED_LIST"},{["name"]="character deleted purge",["help"]="Syntax: .character deleted purge [#keepDays]\r\nCompletely removes all characters from the database that where deleted more than #keepDays ago. If #keepDays not provided the used value from worldserver.conf option 'CharDelete.KeepDays'. If 'CharDelete.KeepDays' option is disabled (set to value 0) then this command can't be used without the specifying #keepDays parameter.",["security"]=4,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_DELETED_OLD"},{["name"]="character deleted restore",["help"]="Syntax: .character deleted restore #guid|$name [$newname] [#new account]\r\n\r\nRestores deleted characters.\r\nIf $name is supplied, only characters with that string in their name will be restored, if $guid is supplied, only the character with that GUID will be restored.\r\nIf $newname is set, the character will be restored with that name instead of the original one. If #newaccount is set, the character will be restored to specific account character list. This works only with one character!",["security"]=3,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_DELETED_RESTORE"},{["name"]="character erase",["help"]="Syntax: .character erase $name\r\n\r\nDelete character $name. Character finally deleted in case any deleting options.",["security"]=4,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_ERASE"},{["name"]="character level",["help"]="Syntax: .character level [$playername] [#level]\r\n\r\nSet the level of character with $playername (or the selected if not name provided) by #numberoflevels Or +1 if no #numberoflevels provided). If #numberoflevels is omitted, the level will be increase by 1. If #numberoflevels is 0, the same level will be restarted. If no character is selected and name not provided, increase your level. Command can be used for offline character. All stats and dependent values recalculated. At level decrease talents can be reset if need. Also at level decrease equipped items with greater level requirement can be lost.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_LEVEL"},{["name"]="character rename",["help"]="Syntax: .character rename [$name] [reserveName] [$newName]\r\n\r\nMark selected in game or by $name in command character for rename at next login.\r\n\r\nIf [reserveName] is 1 then the player's current name is added to the list of reserved names.\r\nIf [newName] then the player will be forced rename.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_RENAME"},{["name"]="character reputation",["help"]="Syntax: .character reputation [$player_name]\r\n\r\nShow reputation information for selected player or player find by $player_name.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_REPUTATION"},{["name"]="character titles",["help"]="Syntax: .character titles [$player_name]\r\n\r\nShow known titles list for selected player or player find by $player_name.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHARACTER_TITLES"},{["name"]="cheat",["help"]="Syntax: .cheat $subcommand\r\nType .cheat to see the list of possible subcommands or .help cheat $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="cheat casttime",["help"]="Syntax: .cheat casttime [on/off]\r\nRemove spells' casting time.",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_CASTTIME"},{["name"]="cheat cooldown",["help"]="Syntax: .cheat cooldown [on/off]\r\nDisable spells' cooldowns.",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_COOLDOWN"},{["name"]="cheat explore",["help"]="Syntax: .cheat explore #flag\r\nReveal or hide all maps for the selected player. If no player is selected, hide or reveal maps to you.\r\nUse a #flag of value 1 to reveal, use a #flag value of 0 to hide all maps.",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_EXPLORE"},{["name"]="cheat god",["help"]="Syntax: .cheat god [on/off]\r\nTurn the user invulnerable.",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_GOD"},{["name"]="cheat power",["help"]="Syntax: .cheat power [on/off]\r\nRemove spells' cost (mana, energy, rage...).",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_POWER"},{["name"]="cheat status",["help"]="Syntax: .cheat status\n\nShows the cheats you currently have enabled.",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_STATUS"},{["name"]="cheat taxi",["help"]="Syntax: .cheat taxi on/off\r\nTemporary grant access to all taxi routes for the selected character.\r\n If no character is selected, hide or reveal all routes to you. Visited taxi nodes are still accessible after removing access.",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_TAXI"},{["name"]="cheat waterwalk",["help"]="Syntax: .cheat waterwalk on/off\r\nAllow to walk on water (self or selected character).",["security"]=2,["source"]="cs_cheat.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_CHEAT_WATERWALK"},{["name"]="combatstop",["help"]="Syntax: .combatstop [$playername]\r\nStop combat for selected character. If selected non-player then command applied to self. If $playername provided then attempt applied to online player $playername.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_COMBATSTOP"},{["name"]="cometome",["help"]="Syntax: .cometome $parameter\nMake selected creature come to your current location (new position not saved to DB).",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_COMETOME"},{["name"]="commands",["help"]="Syntax: .commands\r\n\r\nDisplay a list of available commands for your account level.",["security"]=0,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_COMMANDS"},{["name"]="commentator",["help"]="Syntax: .commentator [on/off]\r\n\r\nEnable or Disable in game Commentator tag or show current state if on/off not provided.",["security"]=1,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_COMMENTATOR"},{["name"]="companion",["help"]="Syntax: .companion\nShow your personal companion (name, race, class), or how to create one if you have none yet.",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="companion create",["help"]="Syntax: .companion create <race> <class> <name>\nClaim your ONE permanent battle companion - a bot that fights at your side and chats/remembers you. Race must match your faction. Races: human orc dwarf nightelf undead tauren gnome troll bloodelf draenei. Classes: warrior paladin hunter rogue priest dk shaman mage warlock druid. Name: 2-12 letters, must be unused.",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="companion dismiss",["help"]="Syntax: .companion dismiss\nSend your companion away. Recall it any time with .companion summon.",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="companion forget",["help"]="Syntax: .companion forget\nRelease your companion permanently: the bond and its memory of you are erased, and the pool character is freed for others. You may then create a new companion.",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="companion summon",["help"]="Syntax: .companion summon\nCall your companion to your side (auto-joins your group and fights with you).",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="cooldown",["help"]="Syntax: .cooldown [#spell_id]\r\n\r\nRemove all (if spell_id not provided) or #spel_id spell cooldown from selected character or you (if no selection).",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_COOLDOWN"},{["name"]="damage",["help"]="Syntax: .damage $damage_amount [$school [$spellid]]\r\n\r\nApply $damage to target. If not $school and $spellid provided then this flat clean melee damage without any modifiers. If $school provided then damage modified by armor reduction (if school physical),\n and target absorbing modifiers and result applied as melee damage to target. If spell provided then damage modified and applied as spell damage. $spellid can be shift-link.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DAMAGE"},{["name"]="debug",["help"]="Syntax: .debug $subcommand\nType .debug to see the list of possible subcommands or .help debug $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="debug anim",["help"]="TODO",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug areatriggers",["help"]="Syntax: .debug areatriggers\nToggle debug mode for areatriggers. In debug mode GM will be notified if reaching an areatrigger",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug arena",["help"]="Syntax: .debug arena\r\n\r\nToggle debug mode for arenas. In debug mode GM can start arena with single player.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug bg",["help"]="Syntax: .debug bg\r\n\r\nToggle debug mode for battlegrounds. In debug mode GM can start battleground with single player.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug boundary",["help"]="Syntax: .debug boundary [duration] [fill] [z]\nOptional arguments:\n- duration: Duration in ms (default: 5000, max: 180000).\n- fill: Fills the boundary with markers.\n- z: Includes z-axis in visualization.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug combat",["help"]="Syntax: .debug combat\nLists PvP and PvE combat references of the selected unit (or self).",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug cooldown",["help"]="Syntax: .debug cooldown #spellID #cooldownTime #itemID\nApply a cooldown of the given duration (in milliseconds) for the given spell and item ID.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug dummy",["help"]="Syntax: .debug dummy <???>\n\nCatch-all debug command. Does nothing by default. If you want it to do things for testing, add the things to its script in cs_debug.cpp.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug entervehicle",["help"]="Syntax: .debug entervehicle #entry #seatID\nEnter the targeted or given vehicle ID in the given seat.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug factionchange",["help"]="Syntax: .debug factionchange [$playerName]\nChecks all faction/race change requirements for the target player and reports pass/fail for each condition (AT_LOGIN flags, guild, arena captain, mail, auctions, gold limit).",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug getitemstate",["help"]="Syntax: .debug getitemstate #itemState [unchanged/changed/new/removed/queue/check_all]\nReturns all items in a given player's inventory with a given item state.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug getitemvalue",["help"]="Syntax: .debug getitemvalue #GUID #index\nReturns the value of the given index for the given item GUID.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug getvalue",["help"]="Syntax: .debug getvalue #index #isInt\nReturns either an integer or float value at a given index of your target.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug hostile",["help"]="Syntax: .debug hostile\nReturns the hostile reference list of a given player.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug itemexpire",["help"]="Syntax: .debug itemexpire #GUID\nDestroy an item with the given GUID.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug lfg",["help"]="Syntax: .debug lfg\r\nToggle debug mode for lfg. In debug mode GM can start lfg queue with one player.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug loot",["help"]="Syntax: .debug loot <type> <id> [count]\nSimulates loot generation for the given loot type and ID, outputting the results to chat without creating items.\nOptional count (1-100) repeats the simulation and shows aggregated drop rates.\nValid types: creature, gameobject, fishing, item, pickpocketing, skinning, disenchant, prospecting, milling, spell, reference, mail, player",["security"]=2,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug lootrecipient",["help"]="Syntax: .debug lootrecipient\nReturns the loot recipient of the targeted creature.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug los",["help"]="Syntax: .debug los\nReturns line of sight status between you and your target.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug mapdata",["help"]="Syntax: .debug mapdata\n\nDisplays debug information about the current map.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug Mod32Value",["help"]="Syntax: .debug Mod32Value #field #value\r\n\r\nAdd #value to field #field of your character.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug moveflags",["help"]="Syntax: .debug moveflags [$newMoveFlags [$newMoveFlags2]]\r\nNo params given will output the current moveflags of the target",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug objectcount",["help"]="Syntax: .debug objectcount <optional map id> Shows the number of Creatures and GameObjects for the specified map id or for all maps if none is specified",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug play",["help"]="Syntax: .debug play $subcommand\nType .debug play to see the list of possible subcommands or .help debug play $subcommand to see info on subcommands.",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="debug play cinematic",["help"]="Syntax: .debug play cinematic #cinematicid\r\n\r\nPlay cinematic #cinematicid for you. You stay at place while your mind fly.\r\n",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug play movie",["help"]="Syntax: .debug play movie #movieid\r\n\r\nPlay movie #movieid for you.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug play music",["help"]="Syntax: .debug play music <musicId>\nPlay music with <musicId>.\nMusic will be played only for you. Other players will not hear this.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug play sound",["help"]="Syntax: .debug play sound #soundid\r\n\r\nPlay sound with #soundid.\r\nSound will be play only for you. Other players do not hear this.\r\nWarning: client may have more 5000 sounds...",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug play visual",["help"]="Syntax: .debug play visual #visualid\r\nPlay spell visual with #visualid.\n#visualid refers to the ID from SpellVisualKit.dbc",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send",["help"]="Syntax: .debug send $subcommand\nType .debug send to see the list of possible subcommands or .help debug send $subcommand to see info on subcommands.",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="debug send buyerror",["help"]="Syntax: .debug send buyerror #error\nSends the given buy error result.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send channelnotify",["help"]="Syntax: .debug send channelnotify #type\nSends a channel notify message of the given type.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send chatmessage",["help"]="Syntax: .debug send chatmessage #type\nSends a chat message of the given type.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send equiperror",["help"]="Syntax: .debug send equiperror #error\nSends the given equip error result.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send largepacket",["help"]="Syntax: .debug send largepacket\nSends a system message of 128 kilobytes.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send opcode",["help"]="Syntax: .debug send opcode\nSends opcodes contained in \"opcode.txt\".",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug send qinvalidmsg",["help"]="Syntax: .debug send qinvalidmsg #error\nSends the given quest error result.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send qpartymsg",["help"]="Syntax: .debug send qpartymsg #message\nSends the given party quest share message.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send sellerror",["help"]="Syntax: .debug send sellerror #error\nSends the given sell error result.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug send setphaseshift",["help"]="Syntax: .debug send setphaseshift #phaseShift\nSends a phase shift message with the given phase shift value.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug send spellfail",["help"]="Syntax: .debug send spellfail #result #failArgument1 #failArgument2\nSends a spell failure message with the given result and argument values.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="debug setaurastate",["help"]="Syntax: .debug setaurastate #state #apply\nSets the selected units aura state using the given apply value.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug setbit",["help"]="Syntax: .debug setbit #index #bit\nSets the unsigned 32-bit integer value of the target at the given index to the given bit.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug setitemvalue",["help"]="Syntax: .debug setitemvalue #GUID #index #value\nSets the value of the given index for the given item GUID to the given value.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug setvalue",["help"]="Syntax: .debug setvalue #index #value\nSets the unsigned 32-bit integer or float value of the target at the given index to the given value.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug setvid",["help"]="Syntax: .debug setvid #ID\nCurrently disabled.\nSets the given target's vehicle ID to the given value.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug spawnvehicle",["help"]="Syntax: .debug spawnvehicle #entry #ID\nCreates a vehicle with the given ID.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug threat",["help"]="Syntax: .debug threat\nReturns the threat list of a given creature.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug threatinfo",["help"]="Syntax: .debug threatinfo\nDisplays various debug information about the target's threat state, modifiers, redirects and similar.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug unitstate",["help"]="Syntax: .debug unitstate [#unitstate]\n\nSets the unit state for the selected unit or displays current unit and react state.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug update",["help"]="Syntax: .debug update #index #value\nSets the unsigned 32-bit integer value of the target at the given index to the given bit.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug uws",["help"]="Syntax: .debug uws #variable #value\nSends a worldstate update for the given variable to the given value.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="debug visibilitydata",["help"]="Syntax: .debug visibilitydata\n\nDisplays debug information related to object visibility around the player.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="debug zonestats",["help"]=".debug zonestats [$playerName]\nDisplays the amount of players in the player's current zone.",["security"]=1,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_INFO"},{["name"]="deserter bg add",["help"]="Syntax: .deserter bg add $playerName <$time>\r\nAdds the bg deserter debuff to a player or your target with $time.\nOptional $time: use a timestring like \"1h15m30s\".Default: 15m",["security"]=3,["source"]="cs_deserter.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DESERTER_BG_ADD"},{["name"]="deserter bg remove",["help"]="Syntax: .deserter bg remove $playerName \n\n Removes the bg deserter debuff from a player or your target.",["security"]=3,["source"]="cs_deserter.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DESERTER_BG_REMOVE"},{["name"]="deserter bg remove all",["help"]="Syntax: .deserter bg remove all <$maxDuration>\r\n Removes the bg deserter debuff from all online and offline players.\nOptional $maxDuration sets the maximum duration to be removed. Use a timestring like \"1h45m\". \"-1\" for any duration. Default: 15m",["security"]=3,["source"]="cs_deserter.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DESERTER_BG_REMOVE"},{["name"]="deserter instance add",["help"]="Syntax: .deserter instance add $playerName <$time>\r\nAdds the instance deserter debuff to a player or your target with $time.\nOptional $time: use a timestring like \"1h15m30s\". Default: 30m",["security"]=3,["source"]="cs_deserter.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DESERTER_INSTANCE_ADD"},{["name"]="deserter instance remove",["help"]="Syntax: .deserter instance remove $playerName \n\n Removes the instance deserter debuff from a player or your target.",["security"]=3,["source"]="cs_deserter.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DESERTER_INSTANCE_REMOVE"},{["name"]="deserter instance remove all",["help"]="Syntax: .deserter instance remove all <$maxDuration>\r\n Removes the instance deserter debuff from all online and offline players.\nOptional $maxDuration sets the maximum duration to be removed. Use a timestring like \"1h45m\". \"-1\" for any duration. Default: 30m",["security"]=3,["source"]="cs_deserter.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DESERTER_INSTANCE_REMOVE"},{["name"]="dev",["help"]="Syntax: .dev [on/off]\r\n\r\nEnable or Disable in game Dev tag or show current state if on/off not provided.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEV"},{["name"]="die",["help"]="Syntax: .die\r\n\r\nKill the selected player. If no player is selected, it will kill you.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DIE"},{["name"]="disable add battleground",["help"]="Syntax: .disable add battleground <entry> <flag> <comment>\n\nDisable a battleground by entry so the core skips it (flag + comment stored).",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_ADD_BATTLEGROUND"},{["name"]="disable add map",["help"]="Syntax: .disable add map <entry> <flag> <comment>\n\nDisable a map by entry so the core skips it (flag + comment stored).",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_ADD_MAP"},{["name"]="disable add outdoorpvp",["help"]="Syntax: .disable add outdoorpvp <entry> <flag> <comment>\n\nDisable an outdoor-PvP zone by entry (flag + comment stored).",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_ADD_OUTDOORPVP"},{["name"]="disable add quest",["help"]="Syntax: .disable add quest <entry> <flag> <comment>\n\nDisable a quest by entry so it cannot be taken (flag + comment stored).",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_ADD_QUEST"},{["name"]="disable add spell",["help"]="Syntax: .disable add spell <entry> <flag> <comment>\n\nDisable a spell by entry so it cannot be cast (flag + comment stored).",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_ADD_SPELL"},{["name"]="disable add vmap",["help"]="Syntax: .disable add vmap <entry> <flag> <comment>\n\nDisable VMAP (line-of-sight/height) for a map by entry.",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_ADD_VMAP"},{["name"]="disable remove battleground",["help"]="Syntax: .disable remove battleground <entry>\n\nRe-enable a previously disabled battleground entry.",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_REMOVE_BATTLEGROUND"},{["name"]="disable remove map",["help"]="Syntax: .disable remove map <entry>\n\nRe-enable a previously disabled map entry.",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_REMOVE_MAP"},{["name"]="disable remove outdoorpvp",["help"]="Syntax: .disable remove outdoorpvp <entry>\n\nRe-enable a previously disabled outdoor-PvP zone entry.",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_REMOVE_OUTDOORPVP"},{["name"]="disable remove quest",["help"]="Syntax: .disable remove quest <entry>\n\nRe-enable a previously disabled quest entry.",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_REMOVE_QUEST"},{["name"]="disable remove spell",["help"]="Syntax: .disable remove spell <entry>\n\nRe-enable a previously disabled spell entry.",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_REMOVE_SPELL"},{["name"]="disable remove vmap",["help"]="Syntax: .disable remove vmap <entry>\n\nRe-enable VMAP for a previously disabled map entry.",["security"]=3,["source"]="cs_disable.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISABLE_REMOVE_VMAP"},{["name"]="dismount",["help"]="Syntax: .dismount\r\n\r\nDismount you, if you are mounted.",["security"]=0,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISMOUNT"},{["name"]="distance",["help"]="Syntax: .distance\r\n\r\nDisplay the distance from your character to the selected creature.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DISTANCE"},{["name"]="event",["help"]="Syntax: .event #event_id\r\nShow details about event with #event_id.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="event activelist",["help"]="Syntax: .event activelist\r\nShow list of currently active events.",["security"]=2,["source"]="cs_event.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_EVENT_ACTIVELIST"},{["name"]="event info",["help"]="Syntax: .event info [event_id]\n\nDisplays information about game events.",["security"]=2,["source"]="cs_event.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_EVENT_INFO"},{["name"]="event start",["help"]="Syntax: .event start #event_id\r\nStart event #event_id. Set start time for event to current moment (change not saved in DB).",["security"]=2,["source"]="cs_event.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_EVENT_START"},{["name"]="event stop",["help"]="Syntax: .event stop #event_id\r\nStop event #event_id. Set start time for event to time in past that make current moment is event stop time (change not saved in DB).",["security"]=2,["source"]="cs_event.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_EVENT_STOP"},{["name"]="flusharenapoints",["help"]="Syntax: .flusharenapoints\r\n\r\nUse it to distribute arena points based on arena team ratings, and start a new week.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_FLUSHARENAPOINTS"},{["name"]="freeze",["help"]="Syntax: .freeze (#player)\r\n\"Freezes\" #player and disables his chat. When using this without #name it will freeze your target.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_FREEZE"},{["name"]="gear epic",["help"]="Syntax: .gear epic\nGear the selected player (or yourself) with EPIC (purple) items for their current level.",["security"]=2,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="gear level",["help"]="Syntax: .gear level\nGear the selected player (or yourself) with level-appropriate UNCOMMON (green) items. Spec-aware, enchanted and gemmed.",["security"]=2,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="gear max",["help"]="Syntax: .gear max\nGear the selected player (or yourself) with the best available items for their current level.",["security"]=2,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="gear rare",["help"]="Syntax: .gear rare\nGear the selected player (or yourself) with RARE (blue) items for their current level.",["security"]=2,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="gear repair",["help"]="Syntax: .gear repair \nRepair all selected player's items.",["security"]=2,["source"]="cs_gear.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GEAR_REPAIR"},{["name"]="gear stats",["help"]="Syntax: .gear stats\n\nShow gear statistics (such as average item level) for the selected player.",["security"]=0,["source"]="cs_gear.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GEAR_STATS"},{["name"]="gear undress",["help"]="Syntax: .gear undress\nMove all equipped items from the selected player (or yourself) into their bags.",["security"]=2,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="gm",["help"]="Syntax: .gm [on/off]\r\n\r\nEnable or Disable in game GM MODE or show current state of on/off not provided.",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="gm chat",["help"]="Syntax: .gm chat [on/off]\r\n\r\nEnable or disable chat GM MODE (show gm badge in messages) or show current state of on/off not provided.",["security"]=2,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM_CHAT"},{["name"]="gm fly",["help"]="Syntax: .gm fly [on/off]\r\nEnable/disable gm fly mode.",["security"]=2,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM_FLY"},{["name"]="gm ingame",["help"]="Syntax: .gm ingame\r\n\r\nDisplay a list of available in game Game Masters.",["security"]=0,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM_INGAME"},{["name"]="gm list",["help"]="Syntax: .gm list\r\n\r\nDisplay a list of all Game Masters accounts and security levels.",["security"]=3,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM_LIST"},{["name"]="gm off",["help"]="Syntax: .gm off\n\nTurns off GM flag.",["security"]=1,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM"},{["name"]="gm on",["help"]="Syntax: .gm on\n\nTurns on GM flag.",["security"]=1,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM"},{["name"]="gm spectator",["help"]="Syntax: .gm spectator on|off\n\nRequires .gm on. Allows the GM character to follow members of the opposite faction. You may need to change zones for the effect to apply.",["security"]=2,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM"},{["name"]="gm visible",["help"]="Syntax: .gm visible on/off\r\n\r\nOutput current visibility state or make GM visible(on) and invisible(off) for other players.",["security"]=2,["source"]="cs_gm.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GM_VISIBLE"},{["name"]="gmannounce",["help"]="Syntax: .gmannounce $announcement\r\nSend an announcement to online Gamemasters.",["security"]=2,["source"]="cs_message.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GMANNOUNCE"},{["name"]="gmnameannounce",["help"]="Syntax: .gmnameannounce $announcement.\r\nSend an announcement to all online GM's, displaying the name of the sender.",["security"]=2,["source"]="cs_message.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GMNAMEANNOUNCE"},{["name"]="gmnotify",["help"]="Syntax: .gmnotify $notification\r\nDisplays a notification on the screen of all online GM's.",["security"]=2,["source"]="cs_message.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GMNOTIFY"},{["name"]="go",["help"]="Syntax: .go $subcommand\nType .go to see the list of possible subcommands or .help go $subcommand to see info on subcommands",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="go creature",["help"]="Syntax: .go creature $creature.guid \r\nTeleports you to the creature using `guid` value of `creature` table.",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go creature id",["help"]="Syntax: .go creature id #creature_entry [#spawn] Teleports you to first (if no #spawn provided) spawn the given creature entry. ",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go creature name",["help"]="Syntax: .go creature name $creature_template.name \r\nTeleports you to a creature using the `name` value of `creature_template` table. \r\nIn the case of multiple creature of the same `name` existing in the world, you will be teleported to the lowest `guid` creature.\r\nWhen running the command for names with spaces don't break the string, example: .go creature name Ruby Scalebane",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go gameobject",["help"]="Syntax: .go gameobject $gameobject.guid\r\nTeleports you to the gameobject using `guid` value of `gameobject` table.",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go gameobject id",["help"]="Syntax: .go gameobject id #gameobject_entry [#spawn] Teleports you to first (if no #spawn provided) spawn the given gameobject entry.",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go graveyard",["help"]="Syntax: .go graveyard #graveyardId\r\n Teleport to graveyard with the graveyardId specified.",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go grid",["help"]="Syntax: .go grid #gridX #gridY [#mapId]\r\n\r\nTeleport the gm to center of grid with provided indexes at map #mapId (or current map if it not provided).",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go quest",["help"]="Syntax: .go quest <starter/ender> <quest>.\nTeleports you to the quest starter/ender creature or object.",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go taxinode",["help"]="Syntax: .go taxinode #taxinode\r\n\r\nTeleport player to taxinode coordinates. You can look up zone using .lookup taxinode $namepart",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go ticket",["help"]="Syntax: .go ticket #ticketid\r\nTeleports the user to the location where $ticketid was created.",["security"]=2,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go trigger",["help"]="Syntax: .go trigger #trigger_id\r\n\r\nTeleport your character to areatrigger with id #trigger_id. Character will be teleported to trigger target if selected areatrigger is telporting trigger.",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go xyz",["help"]="Syntax: .go xyz <x> <y> [<z> [<mapid> [<orientation>]]]\n\nTeleport to the given X Y (optionally Z, map id and orientation) coordinates.",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="go zonexy",["help"]="Syntax: .go zonexy #x #y [#zone]\r\n\r\nTeleport player to point with (#x,#y) client coordinates at ground(water) level in zone #zoneid or current zone if #zoneid not provided. You can look up zone using .lookup area $namepart",["security"]=1,["source"]="cs_go.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GO"},{["name"]="gobject",["help"]="Syntax: .gobject $subcommand\nType .gobject to see the list of possible subcommands or .help gobject $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="gobject activate",["help"]="Syntax: .gobject activate #guid\r\n\r\nActivates an object like a door or a button.",["security"]=2,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_ACTIVATE"},{["name"]="gobject add",["help"]="Syntax: .gobject add #id <spawntimeSecs>\r\n\r\nAdd a game object from game object templates to the world at your current location using the #id.\r\nspawntimesecs sets the spawntime, it is optional.\r\n\r\nNote: this is a copy of .gameobject.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_ADD"},{["name"]="gobject add temp",["help"]="Adds a temporary gameobject that is not saved to DB.",["security"]=2,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_ADD_TEMP"},{["name"]="gobject delete",["help"]="Syntax: .gobject delete #go_guid\r\nDelete gameobject with guid #go_guid.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_DELETE"},{["name"]="gobject despawngroup",["help"]="Syntax: .gobject despawngroup #groupId\r\nDespawns all gameobjects in the given spawn group.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_DELETE"},{["name"]="gobject info",["help"]="Syntax: .gobject info [$object_entry]\r \r Query Gameobject information for selected gameobject or given entry.",["security"]=1,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_INFO"},{["name"]="gobject load",["help"]="Syntax: .gobject load #spawnId\nLoad a gameobject spawn from the database into the world by its GUID.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_LOAD"},{["name"]="gobject move",["help"]="Syntax: .gobject move #goguid [#x #y #z]\r\n\r\nMove gameobject #goguid to character coordinates (or to (#x,#y,#z) coordinates if its provide).",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_MOVE"},{["name"]="gobject near",["help"]="Syntax: .gobject near  [#distance]\r\n\r\nOutput gameobjects at distance #distance from player. Output gameobject guids and coordinates sorted by distance from character. If #distance not provided use 10 as default value.",["security"]=1,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_NEAR"},{["name"]="gobject respawn",["help"]="Syntax: .gobject respawn <guid>\n\nRespawn the selected gameobject, or the one with the given guid.",["security"]=2,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_ACTIVATE"},{["name"]="gobject set",["help"]="Syntax: .gobject set $subcommand\nType .gobject set to see the list of possible subcommands or .help gobject set $subcommand to see info on subcommands.",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="gobject set phase",["help"]="Syntax: .gobject set phase #guid #phasemask\r\n\r\nGameobject with DB guid #guid phasemask changed to #phasemask with related world vision update for players. Gameobject state saved to DB and persistent.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_SET_PHASE"},{["name"]="gobject set state",["help"]="Syntax: .gobject set state #GUIDLow, #objectType, #objectState\nSets the byte value or sends a custom animation for a given gameobject GUID.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_SET_STATE"},{["name"]="gobject spawngroup",["help"]="Syntax: .gobject spawngroup #groupId\r\nSpawns all gameobjects in the given spawn group.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_ADD"},{["name"]="gobject target",["help"]="Syntax: .gobject target [#go_id|#go_name_part]\r\n\r\nLocate and show position nearest gameobject. If #go_id or #go_name_part provide then locate and show position of nearest gameobject with gameobject template id #go_id or name included #go_name_part as part.",["security"]=1,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_TARGET"},{["name"]="gobject turn",["help"]="Syntax: .gobject turn #goguid \r\n\r\nSet for gameobject #goguid orientation same as current character orientation.",["security"]=3,["source"]="cs_gobject.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GOBJECT_TURN"},{["name"]="gps",["help"]="Syntax: .gps [$name|$shift-link]\r\n\r\nDisplay the position information for a selected character or creature (also if player name $name provided then for named player, or if creature/gameobject shift-link provided then pointed creature/gameobject if it loaded). Position information includes X, Y, Z, and orientation, map Id and zone Id",["security"]=1,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GPS"},{["name"]="group",["help"]="Syntax: .group $subcommand\nType .group to see the list of possible subcommands or .help group $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="group disband",["help"]="Syntax: .group disband [$characterName]\n\nDisbands the given character's group.",["security"]=2,["source"]="cs_group.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GROUP_DISBAND"},{["name"]="group join",["help"]="Syntax: .group join $AnyCharacterNameFromGroup [$CharacterName] \r\nAdds to group of player $AnyCharacterNameFromGroup player $CharacterName (or selected).",["security"]=2,["source"]="cs_group.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GROUP_JOIN"},{["name"]="group leader",["help"]="Syntax: .group leader [$characterName]\n\nSets the given character as his group's leader.",["security"]=2,["source"]="cs_group.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GROUP_LEADER"},{["name"]="group list",["help"]="Syntax: .group list [$CharacterName] \r\nLists all the members of the group/party the player is in.",["security"]=2,["source"]="cs_group.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GROUP_LIST"},{["name"]="group remove",["help"]="Syntax: .group remove [$characterName]\n\nRemoves the given character from his group.",["security"]=2,["source"]="cs_group.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GROUP_REMOVE"},{["name"]="group revive",["help"]="Syntax: .group revive $characterName \r\nRevives all group members of the given character or self if not provided.",["security"]=2,["source"]="cs_group.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GROUP_REVIVE"},{["name"]="groupsummon",["help"]="Syntax: .groupsummon [$charactername]\r\n\r\nTeleport the given character and his group to you. Teleported only online characters but original selected group member can be offline.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GROUP_SUMMON"},{["name"]="guid",["help"]="Syntax: .guid\r\n\r\nDisplay the GUID for the selected character.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUID"},{["name"]="guild",["help"]="Syntax: .guild $subcommand\nType .guild to see the list of possible subcommands or .help guild $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="guild create",["help"]="Syntax: .guild create [$GuildLeaderName] \"$GuildName\"\r\n\r\nCreate a guild named $GuildName with the player $GuildLeaderName (or selected) as leader.  Guild name must in quotes.",["security"]=2,["source"]="cs_guild.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUILD_CREATE"},{["name"]="guild delete",["help"]="Syntax: .guild delete \"$GuildName\"\r\n\r\nDelete guild $GuildName. Guild name must in quotes.",["security"]=2,["source"]="cs_guild.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUILD_DELETE"},{["name"]="guild info",["help"]="Shows information about the target's guild or a given Guild Id or Name.",["security"]=2,["source"]="cs_guild.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUILD_INFO"},{["name"]="guild invite",["help"]="Syntax: .guild invite [$CharacterName] \"$GuildName\"\r\n\r\nAdd player $CharacterName (or selected) into a guild $GuildName. Guild name must in quotes.",["security"]=2,["source"]="cs_guild.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUILD_INVITE"},{["name"]="guild rank",["help"]="Syntax: .guild rank [$CharacterName] #RankNumber\r\n\r\nSet for player $CharacterName (or selected) rank #Rank in a guild. Ranks value are numeric, 0 = Guild Master, 1 = Officer, etc...",["security"]=2,["source"]="cs_guild.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUILD_RANK"},{["name"]="guild rename",["help"]="Syntax: .guild rename \"$GuildName\" \"$NewGuildName\" \n\n Rename a guild named $GuildName with $NewGuildName. Guild name and new guild name must in quotes.",["security"]=2,["source"]="cs_guild.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUILD_RENAME"},{["name"]="guild uninvite",["help"]="Syntax: .guild uninvite [$CharacterName]\r\n\r\nRemove player $CharacterName (or selected) from a guild.",["security"]=2,["source"]="cs_guild.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_GUILD_UNINVITE"},{["name"]="hardcore on",["help"]="Syntax: .hardcore on\nEnable hardcore mode on this character. LEVEL 1 ONLY and permanent - if you die, the character becomes a fallen hero and can no longer be played.",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="hardcore status",["help"]="Syntax: .hardcore status\nShow whether this character is normal, hardcore (alive) or fallen.",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="help",["help"]="Syntax: .help [$command]\r\n\r\nDisplay usage instructions for the given $command. If no $command provided show list available commands.",["security"]=0,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_HELP"},{["name"]="hidearea",["help"]="Syntax: .hidearea #areaid\r\n\r\nHide the area of #areaid to the selected character. If no character is selected, hide this area to you.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_HIDEAREA"},{["name"]="honor",["help"]="Syntax: .honor $subcommand\nType .honor to see the list of possible subcommands or .help honor $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="honor add",["help"]="Syntax: .honor add $amount\r\n\r\nAdd a certain amount of honor (gained today) to the selected player.",["security"]=2,["source"]="cs_honor.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_HONOR_ADD"},{["name"]="honor add kill",["help"]="Syntax: .honor add kill\r\n\r\nAdd the targeted unit as one of your pvp kills today (you only get honor if it's a racial leader or a player)",["security"]=2,["source"]="cs_honor.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_HONOR_ADD_KILL"},{["name"]="honor update",["help"]="Syntax: .honor update\r\n\r\nForce the yesterday's honor fields to be updated with today's data, which will get reset for the selected player.",["security"]=2,["source"]="cs_honor.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_HONOR_UPDATE"},{["name"]="instance",["help"]="Syntax: .instance $subcommand\nType .instance to see the list of possible subcommands or .help instance $subcommand to see info on subcommands",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="instance getbossstate",["help"]="Syntax: .instance getbossstate [$Name]\nDisplays the state for every available encounter.\nIf no character name is provided, the current map will be used as target.",["security"]=1,["source"]="cs_instance.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_INSTANCE_GET_BOSS_STATE"},{["name"]="instance listbinds",["help"]="Syntax: .instance listbinds\r\n  Lists the binds of the selected player.",["security"]=1,["source"]="cs_instance.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_INSTANCE_LISTBINDS"},{["name"]="instance savedata",["help"]="Syntax: .instance savedata\r\n  Save the InstanceData for the current player's map to the DB.",["security"]=3,["source"]="cs_instance.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_INSTANCE_SAVEDATA"},{["name"]="instance setbossstate",["help"]="Syntax: .instance setbossstate $bossId $encounterState [$Name]\r\nSets the EncounterState for the given boss id to a new value. EncounterStates range from 0 to 5.\r\nIf no character name is provided, the current map will be used as target.",["security"]=2,["source"]="cs_instance.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_INSTANCE_SET_BOSS_STATE"},{["name"]="instance stats",["help"]="Syntax: .instance stats\n\nShows statistics about instances.",["security"]=1,["source"]="cs_instance.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_INSTANCE_STATS"},{["name"]="instance unbind",["help"]="Syntax: .instance unbind <mapid|all> [difficulty]\r\n  Clear all/some of player's binds",["security"]=2,["source"]="cs_instance.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_INSTANCE_UNBIND"},{["name"]="inventory",["help"]="Syntax: .inventory $subcommand \nType .inventory to see the list of possible subcommands or .help inventory $subcommand to see info on subcommands",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="inventory count",["help"]="Syntax: .inventory count $playerName or $plaerGuid \nCount free slots in bags divided into different bag types.",["security"]=1,["source"]="cs_inventory.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ADDITEM"},{["name"]="item move",["help"]="Syntax: .itemmove #sourceslotid #destinationslotid\r\n\r\nMove an item from slots #sourceslotid to #destinationslotid in your inventory\r\n\r\nNot yet implemented",["security"]=2,["source"]="cs_item.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ITEMMOVE"},{["name"]="item refund",["help"]="Syntax: .item refund <name> <item> <extendedCost> \nRemoves the item and restores honor/arena/items according to extended cost.",["security"]=3,["source"]="cs_item.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ITEM_REFUND"},{["name"]="item restore",["help"]="Syntax: .item restore [#recoveryItemId] [#playername]\r\n\r\nRestore an disposed item for the specified player. Get recoveryId from \".item restore list\" command.",["security"]=2,["source"]="cs_item.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ITEM_RESTORE"},{["name"]="item restore list",["help"]="Syntax: .item restore list [#playername]\r\n\r\nSee restorable items for the specified player.",["security"]=2,["source"]="cs_item.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_ITEM_RESTORE_LIST"},{["name"]="kick",["help"]="Syntax: .kick [$charactername] [$reason]\r\n\r\nKick the given character name from the world with or without reason. If no character name is provided then the selected player (except for yourself) will be kicked. If no reason is provided, default is \"No Reason\".",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_KICK"},{["name"]="learn",["help"]="Syntax: .learn #spell [all]\r\n\r\nSelected character learn a spell of id #spell. If 'all' provided then all ranks learned.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN"},{["name"]="learn all",["help"]="Syntax: .learn all $subcommand\nType .learn all to see the list of possible subcommands or .help learn all $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="learn all crafts",["help"]="Syntax: .learn crafts\r\n\r\nLearn all professions and recipes.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_CRAFTS"},{["name"]="learn all default",["help"]="Syntax: .learn all default [$playername]\r\n\r\nLearn for selected/$playername player all default spells for his race/class and spells rewarded by completed quests.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_DEFAULT"},{["name"]="learn all gm",["help"]="Syntax: .learn all gm\r\n\r\nLearn all default spells for Game Masters.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_GM"},{["name"]="learn all lang",["help"]="Syntax: .learn all lang\r\n\r\nLearn all languages",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_LANG"},{["name"]="learn all my",["help"]="Syntax: .learn all my $subcommand\nType .learn all my to see the list of possible subcommands or .help learn all my $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="learn all my class",["help"]="Syntax: .learn all my class  Learn all spells (trainer, talent, and quest rewards) for your class.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_MY_CLASS"},{["name"]="learn all my pettalents",["help"]="Syntax: .learn all my pettalents\r\n\r\nLearn all talents for your pet available for his creature type (only for hunter pets).",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_MY_PETTALENTS"},{["name"]="learn all my quest",["help"]="Syntax: .learn all my quest  Learn all spells rewarded from quest for your class.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_MY_SPELLS"},{["name"]="learn all my talents",["help"]="Syntax: .learn all my talents\r\n\r\nLearn all talents (and spells with first rank learned as talent) available for his class.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_TALENTS"},{["name"]="learn all my trainer",["help"]="Syntax: .learn all my trainer  Learn all spells taught by trainers for your class.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_MY_SPELLS"},{["name"]="learn all recipes",["help"]="Syntax: .learn all recipes [<profession>]\n\nLearn all recipes of a profession and set its skill to max (e.g. .learn all recipes enchanting).",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEARN_ALL_RECIPES"},{["name"]="levelup",["help"]="Syntax: .levelup [$playername] [#numberoflevels]\r\n\r\nIncrease/decrease the level of character with $playername (or the selected if not name provided) by #numberoflevels Or +1 if no #numberoflevels provided). If #numberoflevels is omitted, the level will be increase by 1. If #numberoflevels is 0, the same level will be restarted. If no character is selected and name not provided, increase your level. Command can be used for offline character. All stats and dependent values recalculated. At level decrease talents can be reset if need. Also at level decrease equipped items with greater level requirement can be lost.",["security"]=2,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LEVELUP"},{["name"]="lfg",["help"]="Syntax: .lfg $subcommand\nType .lfg to see the list of possible subcommands or .help lfg $subcommand to see info on subcommands.",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="lfg clean",["help"]="Syntax: .flg clean\n Cleans current queue, only for debugging purposes.",["security"]=3,["source"]="cs_lfg.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LFG_CLEAN"},{["name"]="lfg cooldown",["help"]="Syntax: .lfg cooldown\nClears all LFG dungeon cooldowns for all players.",["security"]=3,["source"]="cs_lfg.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LFG_COOLDOWN"},{["name"]="lfg group",["help"]="Syntax: .lfg group\n Shows information about all players in the group  (state, roles, comment, dungeons selected).",["security"]=1,["source"]="cs_lfg.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LFG_GROUP"},{["name"]="lfg options",["help"]="Syntax: .lfg options [new value]\n Shows current lfg options. New value is set if extra param is present.",["security"]=2,["source"]="cs_lfg.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LFG_OPTIONS"},{["name"]="lfg player",["help"]="Syntax: .lfg player\n Shows information about player (state, roles, comment, dungeons selected).",["security"]=1,["source"]="cs_lfg.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LFG_PLAYER"},{["name"]="lfg queue",["help"]="Syntax: .lfg queue\n Shows info about current lfg queues.",["security"]=1,["source"]="cs_lfg.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LFG_QUEUE"},{["name"]="linkgrave",["help"]="Syntax: .linkgrave #graveyard_id [alliance|horde]\r\n\r\nLink current zone to graveyard for any (or alliance/horde faction ghosts). This let character ghost from zone teleport to graveyard after die if graveyard is nearest from linked to zone and accept ghost of this faction. Add only single graveyard at another map and only if no graveyards linked (or planned linked at same map).",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LINKGRAVE"},{["name"]="list",["help"]="Syntax: .list $subcommand\nType .list to see the list of possible subcommands or .help list $subcommand to see info on subcommands",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="list auras",["help"]="Syntax: .list auras\nList auras (passive and active) of selected creature or player. If no creature or player is selected, list your own auras.",["security"]=1,["source"]="cs_list.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LIST_AURAS"},{["name"]="list auras id",["help"]="Syntax: .list auras id\n\nLists all active auras on the selected unit by spell ID.",["security"]=1,["source"]="cs_list.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LIST_AURAS"},{["name"]="list auras name",["help"]="Syntax: .list auras name\n\nLists all active auras on the selected unit by spell name.",["security"]=1,["source"]="cs_list.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LIST_AURAS"},{["name"]="list creature",["help"]="Syntax: .list creature #creature_id [#max_count]\r\n\r\nOutput creatures with creature id #creature_id found in world. Output creature guids and coordinates sorted by distance from character. Will be output maximum #max_count creatures. If #max_count not provided use 10 as default value.",["security"]=1,["source"]="cs_list.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LIST_CREATURE"},{["name"]="list item",["help"]="Syntax: .list item #item_id [#max_count]\r\n\r\nOutput items with item id #item_id found in all character inventories, mails, auctions, and guild banks. Output item guids, item owner guid, owner account and owner name (guild name and guid in case guild bank). Will be output maximum #max_count items. If #max_count not provided use 10 as default value.",["security"]=1,["source"]="cs_list.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LIST_ITEM"},{["name"]="list object",["help"]="[DEPRECATED]: use \".list gobject\" instead.\r\nSyntax: .go object #object_guid\r\nTeleport your character to gameobject with guid #object_guid",["security"]=1,["source"]="cs_list.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LIST_OBJECT"},{["name"]="list respawns",["help"]="Syntax: .list respawns [entryId]\r\nIn-game: shows all pending creature and gameobject respawns on the current map, filtered by entryId if provided.\r\nConsole: .list respawns #mapId [#instanceId [#entryId]] - specify map and optional instance ID and entry filter.",["security"]=2,["source"]="cs_list.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LIST_RESPAWNS"},{["name"]="lookup",["help"]="Syntax: .lookup $subcommand\nType .lookup to see the list of possible subcommands or .help lookup $subcommand to see info on subcommands",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="lookup area",["help"]="Syntax: .lookup area $namepart\r\n\r\nLooks up an area by $namepart, and returns all matches with their area ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_AREA"},{["name"]="lookup creature",["help"]="Syntax: .lookup creature $namepart\r\n\r\nLooks up a creature by $namepart, and returns all matches with their creature ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_CREATURE"},{["name"]="lookup event",["help"]="Syntax: .lookup event $name\r\nAttempts to find the ID of the event with the provided $name.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_EVENT"},{["name"]="lookup faction",["help"]="Syntax: .lookup faction $name\r\nAttempts to find the ID of the faction with the provided $name.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_FACTION"},{["name"]="lookup gobject",["help"]="Syntax: .lookup object $objname\r\n\r\nLooks up an gameobject by $objname, and returns all matches with their Gameobject ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_OBJECT"},{["name"]="lookup item",["help"]="Syntax: .lookup item $itemname\r\n\r\nLooks up an item by $itemname, and returns all matches with their Item ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_ITEM"},{["name"]="lookup item set",["help"]="Syntax: .lookup itemset $itemname\r\n\r\nLooks up an item set by $itemname, and returns all matches with their Item set ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_ITEMSET"},{["name"]="lookup map",["help"]="Syntax: .lookup map $namepart\r\n\r\nLooks up a map by $namepart, and returns all matches with their map ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_MAP"},{["name"]="lookup object",["help"]="[DEPRECATED]: use \".lookup gobject\" instead.\r\nSyntax: .go object #object_guid\r\nTeleport your character to gameobject with guid #object_guid",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_OBJECT"},{["name"]="lookup player",["help"]="Syntax: .lookup player $subcommand\nType .lookup player to see the list of possible subcommands or .help lookup player $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="lookup player account",["help"]="Syntax: .lookup player account $account ($limit) \r\n\r\n Searchs players, which account username is $account with optional parametr $limit of results.",["security"]=2,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_PLAYER_ACCOUNT"},{["name"]="lookup player email",["help"]="Syntax: .lookup player email $email ($limit) \r\n\r\n Searchs players, which account email is $email with optional parametr $limit of results.",["security"]=2,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_PLAYER_EMAIL"},{["name"]="lookup player ip",["help"]="Syntax: .lookup player ip $ip ($limit) \r\n\r\n Searchs players, which account ast_ip is $ip with optional parametr $limit of results.",["security"]=2,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_PLAYER_IP"},{["name"]="lookup quest",["help"]="Syntax: .lookup quest $namepart\r\n\r\nLooks up a quest by $namepart, and returns all matches with their quest ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_QUEST"},{["name"]="lookup skill",["help"]="Syntax: .lookup skill $$namepart\r\n\r\nLooks up a skill by $namepart, and returns all matches with their skill ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_SKILL"},{["name"]="lookup spell",["help"]="Syntax: .lookup spell $namepart\r\n\r\nLooks up a spell by $namepart, and returns all matches with their spell ID's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_SPELL"},{["name"]="lookup spell id",["help"]="Syntax: .lookup spell id #spellid\n\nLooks up a spell by #spellid, and returns the match with its spell name.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_SPELL_ID"},{["name"]="lookup taxinode",["help"]="Syntax: .lookup taxinode $substring\r\n\r\nSearch and output all taxinodes with provide $substring in name.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_TAXINODE"},{["name"]="lookup teleport",["help"]="Syntax: .lookup teleport $substring\r\nSearch and output all .teleport command locations with provide $substring in name.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_TELE"},{["name"]="lookup title",["help"]="Syntax: .lookup title $$namepart\r\n\r\nLooks up a title by $namepart, and returns all matches with their title ID's and index's.",["security"]=1,["source"]="cs_lookup.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_LOOKUP_TITLE"},{["name"]="mail",["help"]="Syntax: .mail $subcommand\nType .mail to see a list of subcommands or .help mail $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="mail list",["help"]="Syntax: .mail list [$player]\nDisplays all mail data (except subject and body) for the target player.",["security"]=2,["source"]="cs_mail.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MAIL_LIST"},{["name"]="mail return",["help"]="Syntax: .mail return $player $mailId\nReturns the specified mail to its original sender.",["security"]=2,["source"]="cs_mail.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MAIL_RETURN"},{["name"]="mailbox",["help"]="Syntax: .mailbox\r\n\r\nShow your mailbox content.",["security"]=1,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MAILBOX"},{["name"]="makgora",["help"]="Syntax: .makgora\nWith another hardcore player targeted, challenge them to Mak'gora - a duel to the death. Both must accept; the next duel within 30s is lethal for the loser.",["security"]=0,["source"]="Legends wl_world.command",["dbOnly"]=true,["permission"]=""},{["name"]="maxskill",["help"]="Syntax: .maxskill\r\nSets all skills of the targeted player to their maximum values for its current level.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MAXSKILL"},{["name"]="mmap",["help"]="Syntax: Syntax: .mmaps $subcommand Type .mmaps to see the list of possible subcommands or .help mmaps $subcommand to see info on subcommands",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="mmap loadedtiles",["help"]="Syntax: .mmap loadedtiles to show which tiles are currently loaded",["security"]=3,["source"]="cs_mmaps.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MMAP_LOADEDTILES"},{["name"]="mmap loc",["help"]="Syntax: .mmap loc to print on which tile one is",["security"]=3,["source"]="cs_mmaps.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MMAP_LOC"},{["name"]="mmap path",["help"]="Syntax: .mmap path to calculate and show a path to current select unit",["security"]=3,["source"]="cs_mmaps.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MMAP_PATH"},{["name"]="mmap stats",["help"]="Syntax: .mmap stats to show information about current state of mmaps",["security"]=3,["source"]="cs_mmaps.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MMAP_STATS"},{["name"]="mmap testarea",["help"]="Syntax: .mmap testarea to calculate paths for all nearby npcs to player",["security"]=3,["source"]="cs_mmaps.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MMAP_TESTAREA"},{["name"]="modify",["help"]="Syntax: .modify $subcommand\nType .modify to see the list of possible subcommands or .help modify $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="modify arenapoints",["help"]="Syntax: .modify arenapoints #value\r\nAdd $amount arena points to the selected player.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_ARENAPOINTS"},{["name"]="modify bit",["help"]="Syntax: .modify bit #field #bit\r\n\r\nToggle the #bit bit of the #field field for the selected player. If no player is selected, modify your character.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_BIT"},{["name"]="modify drunk",["help"]="Syntax: .modify drunk #value\r\n Set drunk level to #value (0..100). Value 0 remove drunk state, 100 is max drunked state.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_DRUNK"},{["name"]="modify energy",["help"]="Syntax: .modify energy #energy\r\n\r\nModify the energy of the selected player. If no player is selected, modify your energy.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_ENERGY"},{["name"]="modify faction",["help"]="Syntax: .modify faction #factionid #flagid #npcflagid #dynamicflagid\r\n\r\nModify the faction and flags of the selected creature. Without arguments, display the faction and flags of the selected creature.",["security"]=3,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_FACTION"},{["name"]="modify gender",["help"]="Syntax: .modify gender male/female\r\n\r\nChange gender of selected player.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_GENDER"},{["name"]="modify honor",["help"]="Syntax: .modify honor $amount\r\n\r\nAdd $amount honor points to the selected player.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_HONOR"},{["name"]="modify hp",["help"]="Syntax: .modify hp #newhp\r\n\r\nModify the hp of the selected player. If no player is selected, modify your hp.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_HP"},{["name"]="modify mana",["help"]="Syntax: .modify mana #newmana\r\n\r\nModify the mana of the selected player. If no player is selected, modify your mana.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_MANA"},{["name"]="modify money",["help"]="Syntax: .modify money #money\r\n.money #money\r\n\r\nAdd or remove money to the selected player. If no player is selected, modify your money.\r\n\r\n #gold can be negative to remove money.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_MONEY"},{["name"]="modify mount",["help"]="Syntax: .modify mount #id #speed\nSet CreatureDisplayID as #id and set speed to #speed value between 0.1 - 50.0",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_MOUNT"},{["name"]="modify phase",["help"]="Syntax: .modify phase #phasemask\r\n\r\nSelected character phasemask changed to #phasemask with related world vision update. Change active until in game phase changed, or GM-mode enable/disable, or re-login. Character pts pasemask update to same value.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_PHASE"},{["name"]="modify rage",["help"]="Syntax: .modify rage #newrage\r\n\r\nModify the rage of the selected player. If no player is selected, modify your rage.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_RAGE"},{["name"]="modify reputation",["help"]="Syntax: .modify reputation #repId (#repvalue | $rankname [#delta])\nSets the selected players reputation with faction #repId to #repvalue or to $reprank.\nIf the reputation rank name is provided, the resulting reputation will be the lowest reputation for that rank plus the delta amount, if specified.\nYou can use '.pinfo rep' to list all known reputation ids, or use '.lookup faction $name' to locate a specific faction id.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_REPUTATION"},{["name"]="modify runicpower",["help"]="Syntax: .modify runicpower #newrunicpower\r\n\r\nModify the runic power of the selected player. If no player is selected, modify your runic power.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_RUNICPOWER"},{["name"]="modify scale",["help"]=".modify scale #scale\nModify size of the selected player or creature to \"normal scale\"*rate. If no player or creature is selected, modify your size.\n#rate may range from 0.1 to 10.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SCALE"},{["name"]="modify speed",["help"]="Syntax: .modify speed $speedtype #rate\r\n\r\nModify the running speed of the selected player to \"normal base run speed\"= 1. If no player is selected, modify your speed.\r\n\r\n$speedtypes may be fly, all, walk, backwalk, or swim.\r\n\r\n #rate may range from 0.1 to 50.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SPEED"},{["name"]="modify speed all",["help"]="Syntax: .modify aspeed #rate\r\n\r\nModify all speeds -run,swim,run back,swim back- of the selected player to \"normalbase speed for this move type\"*rate. If no player is selected, modify your speed.\r\n\r\n #rate may range from 0.1 to 50.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SPEED_ALL"},{["name"]="modify speed backwalk",["help"]="Syntax: .modify speed backwalk #rate\r\n\r\nModify the speed of the selected player while running backwards to \"normal walk back speed\"*rate. If no player is selected, modify your speed.\r\n\r\n #rate may range from 0.1 to 50.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SPEED_BACKWALK"},{["name"]="modify speed fly",["help"]=".modify speed fly #rate\nModify the flying speed of the selected player to \"normal flying speed\"*rate. If no player is selected, modify your speed.\n #rate may range from 0.1 to 50.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SPEED_FLY"},{["name"]="modify speed swim",["help"]="Syntax: .modify speed swim #rate\r\n\r\nModify the swim speed of the selected player to \"normal swim speed\"*rate. If no player is selected, modify your speed.\r\n\r\n #rate may range from 0.1 to 50.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SPEED_SWIM"},{["name"]="modify speed walk",["help"]="Syntax: .modify speed bwalk #rate\r\n\r\nModify the speed of the selected player while running to \"normal walk speed\"*rate. If no player is selected, modify your speed.\r\n\r\n #rate may range from 0.1 to 50.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SPEED_WALK"},{["name"]="modify spell",["help"]="TODO",["security"]=4,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_SPELL"},{["name"]="modify standstate",["help"]="Syntax: .modify standstate #emoteid\r\n\r\nChange the emote of your character while standing to #emoteid.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_STANDSTATE"},{["name"]="modify talentpoints",["help"]="Syntax: .modify talentpoints #amount\r\n\r\nSet free talent points for selected character or character's pet. It will be reset to default expected at next levelup/login/quest reward.",["security"]=2,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MODIFY_TALENTPOINTS"},{["name"]="morph",["help"]="Syntax: .morph $subcommand\r\nType .morph to see the list of possible subcommands or \".help morph\" to see info on subcommands",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="morph mount",["help"]="Syntax: .morph mount #displayid - Change the selected target's mount's model ID to #displayid.",["security"]=1,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MORPH"},{["name"]="morph reset",["help"]="Syntax: .morph reset - Doesn't use any parameters to reset the selected target's model",["security"]=1,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEMORPH"},{["name"]="morph target",["help"]="Syntax: .morph target #displayid - Change the selected target's current model id to #displayid.",["security"]=1,["source"]="cs_modify.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MORPH"},{["name"]="movegens",["help"]="Syntax: .movegens\r\n  Show movement generators stack for selected creature or player.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MOVEGENS"},{["name"]="mute",["help"]="Syntax: .mute [$playerName] $mutetime [$reason]\r\nDisible chat messaging for any character from account of character $playerName (or currently selected) at $mutetime time. Player can be offline.\n$mutetime: use a timestring like \"1d15h33s\".",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MUTE"},{["name"]="mutehistory",["help"]="Syntax: .mutehistory $accountName. Shows mute history for an account.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_MUTEHISTORY"},{["name"]="nameannounce",["help"]="Syntax: .nameannounce $announcement.\nSend an announcement to all online players, displaying the name of the sender.",["security"]=2,["source"]="cs_message.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NAMEANNOUNCE"},{["name"]="neargrave",["help"]="Syntax: .neargrave [alliance|horde]\r\n\r\nFind nearest graveyard linked to zone (or only nearest from accepts alliance or horde faction ghosts).",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NEARGRAVE"},{["name"]="notify",["help"]="Syntax: .notify $MessageToBroadcast\r\n\r\nSend a global message to all players online in screen.",["security"]=2,["source"]="cs_message.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NOTIFY"},{["name"]="npc",["help"]="Syntax: .npc $subcommand\nType .npc to see the list of possible subcommands or .help npc $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="npc add",["help"]="Syntax: .npc add #creatureid\r\n\r\nSpawn a creature by the given template id of #creatureid.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_ADD"},{["name"]="npc add formation",["help"]="Syntax: .npc add formation $leader\nAdd selected creature to a leader's formation.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_ADD_FORMATION"},{["name"]="npc add item",["help"]="Syntax: .npc add item #itemId <#maxcount><#incrtime><#extendedcost>r\r\n\r\nAdd item #itemid to item list of selected vendor. Also optionally set max count item in vendor item list and time to item count restoring and items ExtendedCost.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_ADD_ITEM"},{["name"]="npc add move",["help"]="Syntax: .npc add move #creature_guid [#waittime]\r\n\r\nAdd your current location as a waypoint for creature with guid #creature_guid. And optional add wait time.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_ADD_MOVE"},{["name"]="npc add temp",["help"]="Syntax: .npc add temp\r\n\r\nAdds temporary NPC, not saved to database.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_ADD_TEMP"},{["name"]="npc delete",["help"]="Syntax: .npc delete [#guid]\r\n\r\nDelete creature with guid #guid (or the selected if no guid is provided)",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_DELETE"},{["name"]="npc delete item",["help"]="Syntax: .npc delete item #itemId\r\n\r\nRemove item #itemid from item list of selected vendor.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_DELETE_ITEM"},{["name"]="npc despawngroup",["help"]="Syntax: .npc despawngroup #groupId\r\nDespawns all creatures in the given spawn group.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_DESPAWNGROUP"},{["name"]="npc do",["help"]="Syntax: .npc do $action\nRequests the NPC to perform DoAction with the specified ActionID. Used for testing scripts.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_EVADE"},{["name"]="npc follow",["help"]="Syntax: .npc follow start\r\n\r\nSelected creature start follow you until death/fight/etc.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_FOLLOW"},{["name"]="npc follow stop",["help"]="Syntax: .npc follow stop\r\n\r\nSelected creature (non pet) stop follow you.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_FOLLOW_STOP"},{["name"]="npc guid",["help"]="Syntax: .npc guid\r\n\r\nDisplays GUID, faction, NPC flags, Entry ID, Model ID for selected creature.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_INFO"},{["name"]="npc info",["help"]="Syntax: .npc info [#creature_guid]\r\n\r\nDisplay a list of details for the selected creature, or for the creature with the given GUID if no target is selected.\r\n\r\nWhen a creature is targeted or found in the current map, the list includes:\r\n- GUID, Faction, NPC flags, Entry ID, Model ID,\r\n- Level,\r\n- Health (current/maximum),\r\n- Field flags, dynamic flags, faction template,\r\n- Position information,\r\n- and the creature type, e.g. if the creature is a vendor.\r\n\r\nWhen only a GUID is given and the creature is not in the current map, DB-stored data is shown (spawn ID, entry, phase, position, map, etc.).",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_INFO"},{["name"]="npc load",["help"]="Syntax: .npc load #spawnId\nLoad a creature spawn from the database into the world by its GUID.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_LOAD"},{["name"]="npc move",["help"]="Syntax: .npc move [#creature_guid]\r\n\r\nMove the targeted creature spawn point to your coordinates.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_MOVE"},{["name"]="npc near",["help"]="Syntax: .npc near #distance\nReturns all database creature spawns in a given distance.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_NEAR"},{["name"]="npc playemote",["help"]="Syntax: .npc playemote #emoteid\r\n\r\nMake the selected creature emote with an emote of id #emoteid.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_PLAYEMOTE"},{["name"]="npc say",["help"]="Syntax: .npc say $message\nMake selected creature say specified message.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SAY"},{["name"]="npc set",["help"]="Syntax: .npc set $subcommand\nType .npc set to see the list of possible subcommands or .help npc set $subcommand to see info on subcommands.",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="npc set allowmove",["help"]="Syntax: .npc set allowmove\r\n\r\nEnable or disable movement creatures in world. Not implemented.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_ALLOWMOVE"},{["name"]="npc set data",["help"]="Syntax: .npc set data $field $data\nSets data for the selected creature. Used for testing Scripting",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_DATA"},{["name"]="npc set entry",["help"]="Syntax: .npc set entry $entry\nSwitch selected creature with another entry from creature_template. - New creature.id value not saved to DB.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_ENTRY"},{["name"]="npc set faction original",["help"]="Syntax: .npc set faction original\r\n\r\nRevert the temporal faction of the selected creature.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_FACTIONID"},{["name"]="npc set faction permanent",["help"]="Syntax: .npc set faction permanent #factionid\r\n\r\nPermanently set the faction of the selected creature to #factionid.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_FACTIONID"},{["name"]="npc set faction temp",["help"]="Syntax: .npc set faction temp #factionid\r\n\r\nTemporarily set the faction of the selected creature to #factionid.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_FACTIONID"},{["name"]="npc set flag",["help"]="Syntax: .npc set flag #npcflag\r\n\r\nSet the NPC flags of creature template of the selected creature and selected creature to #npcflag. NPC flags will applied to all creatures of selected creature template after server restart or grid unload/load.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_FLAG"},{["name"]="npc set level",["help"]="Syntax: .npc set level #level\r\n\r\nChange the level of the selected creature to #level.\r\n\r\n#level may range from 1 to (CONFIG_MAX_PLAYER_LEVEL) + 3.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_LEVEL"},{["name"]="npc set link",["help"]="Syntax: .npc set link $creatureGUID\r\n\r\nLinks respawn of selected creature to the condition that $creatureGUID defined is alive.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_LINK"},{["name"]="npc set model",["help"]="Syntax: .npc set model #displayid\r\n\r\nChange the model id of the selected creature to #displayid.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_MODEL"},{["name"]="npc set movetype",["help"]="Syntax: .npc set movetype [#creature_guid] stay/random/way [NODEL]\r\n\r\nSet for creature pointed by #creature_guid (or selected if #creature_guid not provided) movement type and move it to respawn position (if creature alive). Any existing waypoints for creature will be removed from the database if you do not use NODEL. If the creature is dead then movement type will applied at creature respawn.\r\nMake sure you use NODEL, if you want to keep the waypoints.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_MOVETYPE"},{["name"]="npc set phase",["help"]="Syntax: .npc set phase #phasemask\r\n\r\nSelected unit or pet phasemask changed to #phasemask with related world vision update for players. In creature case state saved to DB and persistent. In pet case change active until in game phase changed for owner, owner re-login, or GM-mode enable/disable..",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_PHASE"},{["name"]="npc set spawntime",["help"]="Syntax: .npc set spawntime #time\r\nAdjust spawntime of selected creature to #time.\n#time: use a timestring like \"10m30s\".",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_SPAWNTIME"},{["name"]="npc set wanderdistance",["help"]="Syntax: .npc set wanderdistance #dist\r\n\r\nAdjust wander distance of selected creature to dist.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SET_SPAWNDIST"},{["name"]="npc spawngroup",["help"]="Syntax: .npc spawngroup #groupId\r\nSpawns all creatures in the given spawn group.",["security"]=3,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_SPAWNGROUP"},{["name"]="npc tame",["help"]="Syntax: .npc tame\nCreates a player pet of the targeted creature.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_TAME"},{["name"]="npc textemote",["help"]="Syntax: .npc textemote #emoteid\r\n\r\nMake the selected creature to do textemote with an emote of id #emoteid.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_TEXTEMOTE"},{["name"]="npc whisper",["help"]="Syntax: .npc whisper #playername #text\r\nMake the selected npc whisper #text to  #playername.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_WHISPER"},{["name"]="npc yell",["help"]="Syntax: .npc yell $message\nMake selected creature yell specified message.",["security"]=2,["source"]="cs_npc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_NPC_YELL"},{["name"]="opendoor",["help"]="Syntax: .opendoor [$range]\nOpens the nearest door within the range provided (default 5.0yd)",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_OPENDOOR"},{["name"]="packetlog",["help"]="Syntax: .packetlog [on/off]\n Toggles to allow the character using the command to start to log their packets into the server, PacketLogFile needs to be set with a valid filename",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_PACKETLOG"},{["name"]="pdump",["help"]="Syntax: .pdump $subcommand\nType .pdump to see the list of possible subcommands or .help pdump $subcommand to see info on subcommands",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="pdump copy",["help"]="Syntax: .pdump copy $playerNameOrGUID $account [$newname] [$newguid]\nCopy character with name/guid $playerNameOrGUID into character list of $account with $newname, with first free or $newguid guid.",["security"]=3,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_PDUMP_COPY"},{["name"]="pdump load",["help"]="Syntax: .pdump load $filename $account [$newname] [$newguid]\r\nLoad character dump from dump file into character list of $account with saved or $newname, with saved (or first free) or $newguid guid.",["security"]=3,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_PDUMP_LOAD"},{["name"]="pdump write",["help"]="Syntax: .pdump write $filename $playerNameOrGUID\r\nWrite character dump with name/guid $playerNameOrGUID to file $filename.",["security"]=3,["source"]="cs_character.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_PDUMP_WRITE"},{["name"]="pet",["help"]="Syntax: .pet $subcommand\nType .pet to see the list of possible subcommands or .help pet $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="pet create",["help"]="Syntax: .pet create\r\n\r\nCreates a pet of the selected creature.",["security"]=2,["source"]="cs_pet.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_PET_CREATE"},{["name"]="pet delete",["help"]="Syntax: .pet delete $playerNameOrGUID #petNumber\nDeletes the pet with the given pet number belonging to the specified player.",["security"]=3,["source"]="cs_pet.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_PET_DELETE"},{["name"]="pet learn",["help"]="Syntax: .pet learn\r\n\r\nLearn #spellid to pet.",["security"]=2,["source"]="cs_pet.cpp",["dbOnly"]=false,["permission"]=