SSESS"},{["name"]="quest",["help"]="Syntax: .quest $subcommand\nType .quest to see the list of possible subcommands or .help quest $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="quest add",["help"]="Syntax: .quest add #quest_id\r\n\r\nAdd to character quest log quest #quest_id. Quest started from item can't be added by this command but correct .additem call provided in command output.",["security"]=2,["source"]="cs_quest.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_QUEST_ADD"},{["name"]="quest complete",["help"]="Syntax: .quest complete #questid\r\nMark all quest objectives as completed for target character active quest. After this target character can go and get quest reward.",["security"]=2,["source"]="cs_quest.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_QUEST_COMPLETE"},{["name"]="quest remove",["help"]="Syntax: .quest remove #quest_id\r\n\r\nSet quest #quest_id state to not completed and not active (and remove from active quest list) for selected player.",["security"]=2,["source"]="cs_quest.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_QUEST_REMOVE"},{["name"]="quest reward",["help"]="Syntax: .quest reward #questId\n\nGrants quest reward to selected player and removes quest from his log (quest must be in completed state).",["security"]=2,["source"]="cs_quest.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_QUEST_REWARD"},{["name"]="quest status",["help"]="Syntax: .quest status $id [$name]. Displays the selected player's status for the specified quest.",["security"]=2,["source"]="cs_quest.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_QUEST"},{["name"]="rbac list",["help"]="Syntax: .rbac list [#id]\nView list of all permissions. If #id is given will show only info for that permission.",["security"]=3,["source"]="cs_rbac.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RBAC_LIST"},{["name"]="r