ssion"]="rbac::RBAC_PERM_COMMAND_RELOAD_VEHICLE_ACCESSORY"},{["name"]="reload vehicle_template_accessory",["help"]="Syntax: .reload vehicle_template_accessory\n\nReloads entry-based vehicle accessory definitions from the database.",["security"]=3,["source"]="cs_reload.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RELOAD_VEHICLE_TEMPLATE_ACCESSORY"},{["name"]="reload warden_action",["help"]="Syntax: .reload warden_action\n\nReloads warden_action table.",["security"]=3,["source"]="cs_reload.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RELOAD"},{["name"]="reload waypoint_data",["help"]="Syntax: .reload waypoint_data\n\nReload the waypoint_data (creature path) table from the database.",["security"]=3,["source"]="cs_reload.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RELOAD_WAYPOINT_DATA"},{["name"]="reload waypoint_scripts",["help"]="Syntax: .reload waypoint_scripts\nReload waypoint_scripts table.",["security"]=3,["source"]="cs_reload.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RELOAD_WAYPOINT_SCRIPTS"},{["name"]="reset",["help"]="Syntax: .reset $subcommand\nType .reset to see the list of possible subcommands or .help reset $subcommand to see info on subcommands",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="reset achievements",["help"]="Syntax: .reset achievements [$playername]\r\n\r\nReset achievements data for selected or named (online or offline) character. Achievements for persistance progress data like completed quests/etc re-filled at reset. Achievements for events like kills/casts/etc will lost.",["security"]=4,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET_ACHIEVEMENTS"},{["name"]="reset all",["help"]="Syntax: .reset all spells\r\n\r\nSyntax: .reset all talents\r\n\r\nSyntax: .reset all honor\r\n\r\nSyntax: .reset all arena\r\n\r\nRequests a reset of spells or talents (including talents for all of a character's pets, if any) at the next login for each existing character, or immediately resets honor points or arena points for all characters.",["security"]=4,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET_ALL"},{["name"]="reset honor",["help"]="Syntax: .reset honor [Playername]\r\n  Reset all honor data for targeted character.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET_HONOR"},{["name"]="reset items",["help"]="Syntax : .reset items equipped|bags|bank|keyring|currency|vendor_buyback|all|allbags #playername\nDelete items in the player inventory (equipped, bank, bags etc...) depending on the chosen option.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="reset items all",["help"]="Syntax : .reset items all #playername\nDelete all items in the selected player's inventory (equipped, in bags, in bank, in keyring, in currency list and in vendor buy back tab).\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset items allbags",["help"]="Syntax : .reset items allbags #playername\nDelete all items in the selected player's inventory (equipped, in bags, in bank, in keyring, in currency list and in vendor buy back tab)\nThis command also deletes the bags.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset items bags",["help"]="Syntax : .reset items bags #playername\nDelete all items in the selected player's bags.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset items bank",["help"]="Syntax : .reset items bank #playername\nDelete all items in the selected player's bank.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset items currency",["help"]="Syntax : .reset items currency #playername\nDelete all items in the selected player's currencies list.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset items equipped",["help"]="Syntax : .reset items equipped #playername\nDelete all items equipped on the target player.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset items keyring",["help"]="Syntax : .reset items keyring #playername\nDelete all items in the selected player's keyring.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset items vendor_buyback",["help"]="Syntax : .reset items vendor_buyback #playername\nDelete all items in the selected player's vendor buyback tab.\n#playername : Optional target player name (if player is online only). If not provided the command will execute on the selected target player.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET"},{["name"]="reset level",["help"]="Syntax: .reset level [Playername]\r\n  Reset level to 1 including reset stats and talents.  Equipped items with greater level requirement can be lost.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET_LEVEL"},{["name"]="reset spells",["help"]="Syntax: .reset spells [Playername]\r\n  Removes all non-original spells from spellbook.\r\n. Playername can be name of offline character.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET_SPELLS"},{["name"]="reset stats",["help"]="Syntax: .reset stats [Playername]\r\n  Resets(recalculate) all stats of the targeted player to their original VALUESat current level.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET_STATS"},{["name"]="reset talents",["help"]="Syntax: .reset talents [Playername]\r\n  Removes all talents of the targeted player or pet or named player. Playername can be name of offline character. With player talents also will be reset talents for all character's pets if any.",["security"]=3,["source"]="cs_reset.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESET_TALENTS"},{["name"]="respawn",["help"]="Syntax: .respawn\nRespawn the selected unit without waiting respawn time expiration.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESPAWN"},{["name"]="respawn all",["help"]="Syntax: .respawn all\nRespawn all nearest creatures and GO without waiting respawn time expiration.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESPAWN_ALL"},{["name"]="respawn creature entry",["help"]="Syntax: .respawn creature entry #entry [#mapId [#instanceId]]\r\nIn-game: forces all creatures with the given #entry to respawn on the current map.\r\nConsole: specify #mapId (required) and optionally #instanceId. Pooled creatures are skipped in the queue phase to prevent duplicate spawns.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESPAWN_CREATURE_ENTRY"},{["name"]="respawn creature guid",["help"]="Syntax: .respawn creature guid #spawnGuid\r\nForces the creature with the given spawn GUID (database GUID) to respawn. Usable from console.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESPAWN_CREATURE_GUID"},{["name"]="respawn gameobject entry",["help"]="Syntax: .respawn gameobject entry #entry [#mapId [#instanceId]]\r\nIn-game: forces all gameobjects with the given #entry to respawn on the current map.\r\nConsole: specify #mapId (required) and optionally #instanceId. Pooled gameobjects are skipped in the queue phase to prevent duplicate spawns.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESPAWN_GAMEOBJECT_ENTRY"},{["name"]="respawn gameobject guid",["help"]="Syntax: .respawn gameobject guid #spawnGuid\r\nForces the gameobject with the given spawn GUID (database GUID) to respawn. Usable from console.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_RESPAWN_GAMEOBJECT_GUID"},{["name"]="revive",["help"]="Syntax: .revive\r\n\r\nRevive the selected player. If no player is selected, it will revive you.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_REVIVE"},{["name"]="save",["help"]="Syntax: .save\r\n\r\nSaves your character.",["security"]=0,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SAVE"},{["name"]="saveall",["help"]="Syntax: .saveall\r\n\r\nSave all characters in game.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SAVEALL"},{["name"]="send",["help"]="Syntax: send $subcommand\n Type .send to see a list of possible subcommands\n or .help send $subcommand to see info on the subcommand.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="send items",["help"]="Syntax: .send items #playername \"#subject\" \"#text\" itemid1[:count1] itemid2[:count2] ... itemidN[:countN]\r\n\r\nSend a mail to a player. Subject and mail text must be in \"\". If for itemid not provided related count values then expected 1, if count > max items in stack then items will be send in required amount stacks. All stacks amount in mail limited to 12.",["security"]=2,["source"]="cs_send.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SEND_ITEMS"},{["name"]="send mail",["help"]="Syntax: .send mail #playername \"#subject\" \"#text\"\r\n\r\nSend a mail to a player. Subject and mail text must be in \"\".",["security"]=2,["source"]="cs_send.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SEND_MAIL"},{["name"]="send message",["help"]="Syntax: .send message $playername $message\r\n\r\nSend screen message to player from ADMINISTRATOR.",["security"]=3,["source"]="cs_send.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SEND_MESSAGE"},{["name"]="send money",["help"]="Syntax: .send money #playername \"#subject\" \"#text\" #money\r\n\r\nSend mail with money to a player. Subject and mail text must be in \"\".",["security"]=2,["source"]="cs_send.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SEND_MONEY"},{["name"]="server",["help"]="Syntax: .server $subcommand\nType .server to see the list of possible subcommands or .help server $subcommand to see info on subcommands",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="server corpses",["help"]="Syntax: .server corpses\r\n\r\nTriggering corpses expire check in world.",["security"]=2,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_CORPSES"},{["name"]="server debug",["help"]="Syntax: .server debug\r\nShows detailed information about the server setup, useful when reporting a bug.",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_DEBUG"},{["name"]="server exit",["help"]="Syntax: .server exit\r\n\r\nTerminate AzerothCore NOW. Exit code 0.",["security"]=4,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_EXIT"},{["name"]="server idlerestart",["help"]="Syntax: .server idlerestart #delay\r\nRestart the server after #delay if no active connections are present (no players). Use #exist_code or 2 as program exist code.\n#delay: use a timestring like \"1h15m30s\".",["security"]=4,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_IDLERESTART"},{["name"]="server idlerestart cancel",["help"]="Syntax: .server idlerestart cancel\r\n\r\nCancel the restart/shutdown timer if any.",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_IDLERESTART_CANCEL"},{["name"]="server idleshutdown",["help"]="Syntax: .server idleshutdown #delay [#exist_code]\r\nShut the server down after #delay if no active connections are present (no players). Use #exist_code or 0 as program exist code.\n#delay: use a timestring like \"1h15m30s\".",["security"]=4,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_IDLESHUTDOWN"},{["name"]="server idleshutdown cancel",["help"]="Syntax: .server idleshutdown cancel\r\n\r\nCancel the restart/shutdown timer if any.",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_IDLESHUTDOWN_CANCEL"},{["name"]="server info",["help"]="Syntax: .server info\r\n\r\nDisplay server version and the number of connected players.",["security"]=0,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_INFO"},{["name"]="server motd",["help"]="Syntax: .server motd\r\n\r\nShow server Message of the day.",["security"]=0,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_MOTD"},{["name"]="server restart",["help"]="Syntax: .server restart #delay\r\nRestart the server after #delay. Use #exist_code or 2 as program exist code.\n#delay: use a timestring like \"1h15m30s\".",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_RESTART"},{["name"]="server restart cancel",["help"]="Syntax: .server restart cancel\r\n\r\nCancel the restart/shutdown timer if any.",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_RESTART_CANCEL"},{["name"]="server set closed",["help"]="Syntax: server set closed on/off\r\n\r\nSets whether the world accepts new client connectsions.",["security"]=4,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_SET_CLOSED"},{["name"]="server set loglevel",["help"]="Syntax: .server set loglevel $facility $name $loglevel. $facility can take the values: appender (a) or logger (l). $loglevel can take the values: disabled (0),\n trace (1),\n debug (2),\n info (3),\n warn (4),\n error (5) or fatal (6)",["security"]=4,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_SET_LOGLEVEL"},{["name"]="server set motd",["help"]="Syntax: .server set motd Optional($realmId) Optional($locale) $MOTD\r \r Set server Message of the day for the specified $realmId.\r If $realmId is not provided it will update for the current realm. \r Use $realmId -1 to set motd for all realms. If $locale is not provided enUS will be used.",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_SET_MOTD"},{["name"]="server shutdown",["help"]="Syntax: .server shutdown #delay [#exit_code]\r\nShut the server down after #delay. Use #exit_code or 0 as program exit code.\n#delay: use a timestring like \"1h15m30s\".",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_SHUTDOWN"},{["name"]="server shutdown cancel",["help"]="Syntax: .server shutdown cancel\r\n\r\nCancel the restart/shutdown timer if any.",["security"]=3,["source"]="cs_server.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SERVER_SHUTDOWN_CANCEL"},{["name"]="setskill",["help"]="Syntax: .setskill #skill #level [#max]\r\n\r\nSet a skill of id #skill with a current skill value of #level and a maximum value of #max (or equal current maximum if not provide) for the selected character. If no character is selected, you learn the skill.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SETSKILL"},{["name"]="settings",["help"]="Syntax: .settings $subcommand\nType .setting to see the list of all available commands.",["security"]=1,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="settings announcer",["help"]="Syntax: .settings announcer <type> <on/off>.\nDisables receiving announcements. Valid announcement types are: 'autobroadcast', 'arena' and 'bg'",["security"]=1,["source"]="cs_player_settings.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SETTINGS_ANNOUNCER"},{["name"]="showarea",["help"]="Syntax: .showarea #areaid\r\n\r\nReveal the area of #areaid to the selected character. If no character is selected, reveal this area to you.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SHOWAREA"},{["name"]="skirmish",["help"]="Syntax: .skirmish [arena] [XvX] [Nick1] [Nick2] ... [NickN]\n[arena] can be \"all\" or comma-separated list of possible arenas (NA, BE, RL, DS, RV).\n[XvX] can be 1v1, 2v2, 3v3, 5v5. After [XvX] specify enough nicknames for that mode.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SKIRMISH"},{["name"]="spect",["help"]="Syntax: .spect $subcommand\nType .spect to see the list of possible subcommands or .help spect $subcommand to see info on subcommands.",["security"]=0,["source"]="cs_spectator.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPECT"},{["name"]="spect leave",["help"]="Syntax: .spect leave\nLeave an arena you are spectating.",["security"]=0,["source"]="cs_spectator.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPECT_LEAVE"},{["name"]="spect reset",["help"]="Syntax: .spect reset\nReset various values related to spectating.",["security"]=0,["source"]="cs_spectator.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPECT_RESET"},{["name"]="spect spectate",["help"]="Syntax: .spect spectate #name\nBegin spectating the given player.",["security"]=0,["source"]="cs_spectator.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPECT_SPECTATE"},{["name"]="spect version",["help"]="Syntax: .spect version #version\nVerify addon version for arena spectating.",["security"]=0,["source"]="cs_spectator.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPECT_VERSION"},{["name"]="spect watch",["help"]="Syntax: .spect watch #name\nBegin watching the given player.",["security"]=0,["source"]="cs_spectator.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPECT_WATCH"},{["name"]="spellinfo",["help"]="Syntax: .spellinfo $subcommand\n\nType .spellinfo to see a list of subcommands or .help spellinfo $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="spellinfo all",["help"]="Syntax: .spellinfo all #spellid\n\nDisplays all available data for spell #spellid including attributes, general properties, effects and targets.",["security"]=2,["source"]="cs_spellinfo.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPELLINFO_ALL"},{["name"]="spellinfo attributes",["help"]="Syntax: .spellinfo attributes #spellid\n\nDisplays basic info and attribute flags for spell #spellid including SpellAttr0-7, custom attributes, stances, dispel type and mechanic.",["security"]=2,["source"]="cs_spellinfo.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPELLINFO_ATTRIBUTES"},{["name"]="spellinfo effects",["help"]="Syntax: .spellinfo effects #spellid\n\nDisplays effect data for spell #spellid including effect type, aura type, base points, multipliers, misc values, mechanic, trigger spell, amplitude and class mask per effect.",["security"]=2,["source"]="cs_spellinfo.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPELLINFO_EFFECTS"},{["name"]="spellinfo targets",["help"]="Syntax: .spellinfo targets #spellid\n\nDisplays target data for spell #spellid including target mask, creature type, max affected targets, and per-effect TargetA, TargetB, radius and chain targets.",["security"]=2,["source"]="cs_spellinfo.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SPELLINFO_TARGETS"},{["name"]="string",["help"]="Syntax: .string <id> [<locale>]\n\nPrint the localized acore_string text for the given string id.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_STRING"},{["name"]="summon",["help"]="Syntax: .summon [$charactername]\r\n\r\nTeleport the given character to you. Character can be offline.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_SUMMON"},{["name"]="teleport",["help"]="Syntax: .teleport #location\r\nTeleport player to a given location.",["security"]=2,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE"},{["name"]="teleport add",["help"]="Syntax: .teleport add $name\r\nAdd current your position to .teleport command target locations list with name $name.",["security"]=3,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE_ADD"},{["name"]="teleport del",["help"]="Syntax: .teleport del $name\r\nRemove location with name $name for .teleport command locations list.",["security"]=3,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE_DEL"},{["name"]="teleport group",["help"]="Syntax: .teleport group#location\r\nTeleport a selected player and his group members to a given location.",["security"]=2,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE_GROUP"},{["name"]="teleport name",["help"]="Syntax: .teleport name [#playername] #location\r\nTeleport the given character to a given location. Character can be offline.\r\nTo teleport to homebind, set #location to \"$home\" (without quotes).",["security"]=2,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE_NAME"},{["name"]="teleport name npc guid",["help"]="Syntax: .teleport name id #playername #creatureSpawnId\nTeleport the given character to creature with spawn id #creatureSpawnId. Character can be offline.",["security"]=2,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE_NAME"},{["name"]="teleport name npc id",["help"]="Syntax: .teleport name id #playername #creatureId\nTeleport the given character to first found creature with id #creatureId. Character can be offline.",["security"]=2,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE_NAME"},{["name"]="teleport name npc name",["help"]="Syntax: .teleport name id #playername #creatureName\nTeleport the given character to first found creature with name (must match exactly) #creatureName. Character can be offline.",["security"]=2,["source"]="cs_tele.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TELE_NAME"},{["name"]="ticket",["help"]="Syntax: .ticket $subcommand\nType .ticket to see the list of possible subcommands or .help ticket $subcommand to see info on subcommands",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="ticket assign",["help"]="Usage: .ticket assign $ticketid $gmname.\r\nAssigns the specified ticket to the specified Game Master.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_ASSIGN"},{["name"]="ticket close",["help"]="Usage: .ticket close $ticketid.\r\nCloses the specified ticket. Does not delete permanently.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_CLOSE"},{["name"]="ticket closedlist",["help"]="Displays a list of closed GM tickets.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_CLOSEDLIST"},{["name"]="ticket comment",["help"]="Usage: .ticket comment $ticketid $comment.\r\nAllows the adding or modifying of a comment to the specified ticket.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_COMMENT"},{["name"]="ticket complete",["help"]="Syntax: .ticket complete #ticketID\nMark a ticket of the given ID as complete.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_COMPLETE"},{["name"]="ticket delete",["help"]="Usage: .ticket delete $ticketid.\r\nDeletes the specified ticket permanently. Ticket must be closed first.",["security"]=3,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_DELETE"},{["name"]="ticket escalate",["help"]="Syntax: .ticket escalate #ticketID\nAdd a ticket of the given ID to the escalation queue.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_ESCALATE"},{["name"]="ticket escalatedlist",["help"]="Syntax: .ticket escalatedlist\nReturn all open tickets in the escalation queue.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_ESCALATEDLIST"},{["name"]="ticket list",["help"]="Displays a list of open GM tickets.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_LIST"},{["name"]="ticket onlinelist",["help"]="Displays a list of open GM tickets whose owner is online.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_ONLINELIST"},{["name"]="ticket reset",["help"]="Syntax: .ticket reset\nRemoves all closed tickets and resets the counter, if no pending open tickets are existing.",["security"]=4,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_RESET"},{["name"]="ticket response",["help"]="Syntax: .ticket response $subcommand\nType .ticket response to see the list of possible subcommands or .help ticket response $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="ticket response append",["help"]="Add a response\n\nSyntax: ticket response append $ticketId $response",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_RESPONSE_APPEND"},{["name"]="ticket response appendln",["help"]="Add a response to a new line.\n\nSyntax: ticket response appendln $ticketId $response",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_RESPONSE_APPENDLN"},{["name"]="ticket response delete",["help"]="Delete a ticket response\n\nSyntax: ticket response delete $ticketId",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_RESPONSE"},{["name"]="ticket response show",["help"]="Show a ticket response\n\nSyntax: ticket response show $ticketId",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_RESPONSE"},{["name"]="ticket togglesystem",["help"]="Syntax: .ticket togglesystem\nToggle whether tickets are allowed or disallowed.",["security"]=3,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_TOGGLESYSTEM"},{["name"]="ticket unassign",["help"]="Usage: .ticket unassign $ticketid.\r\nUnassigns the specified ticket from the current assigned Game Master.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_UNASSIGN"},{["name"]="ticket viewid",["help"]="Usage: .ticket viewid $ticketid.\r\nReturns details about specified ticket. Ticket must be open and not deleted.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_VIEWID"},{["name"]="ticket viewname",["help"]="Usage: .ticket viewname $creatorname. \r\nReturns details about specified ticket. Ticket must be open and not deleted.",["security"]=2,["source"]="cs_ticket.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TICKET_VIEWNAME"},{["name"]="titles",["help"]="Syntax: .titles $subcommand\nType .titles to see the list of possible subcommands or .help titles $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="titles add",["help"]="Syntax: .titles add #title\r\nAdd title #title (id or shift-link) to known titles list for selected player.",["security"]=2,["source"]="cs_titles.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TITLES_ADD"},{["name"]="titles current",["help"]="Syntax: .titles current #title\r\nSet title #title (id or shift-link) as current selected titl for selected player. If title not in known title list for player then it will be added to list.",["security"]=2,["source"]="cs_titles.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TITLES_CURRENT"},{["name"]="titles remove",["help"]="Syntax: .titles remove #title\r\nRemove title #title (id or shift-link) from known titles list for selected player.",["security"]=2,["source"]="cs_titles.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TITLES_REMOVE"},{["name"]="titles set",["help"]="Syntax: .titles set $subcommand\nType .titles set to see the list of possible subcommands or .help titles set $subcommand to see info on subcommands.",["security"]=2,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="titles set mask",["help"]="Syntax: .titles set mask #mask\r\n\r\nAllows user to use all titles from #mask.\r\n\r\n #mask=0 disables the title-choose-field",["security"]=2,["source"]="cs_titles.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_TITLES_SET_MASK"},{["name"]="unaura",["help"]="Syntax: .unaura #spellid\r\n\r\nRemove aura due to spell #spellid from the selected Unit.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNAURA"},{["name"]="unban",["help"]="Syntax: .unban $subcommand\nType .unban to see the list of possible subcommands or .help unban $subcommand to see info on subcommands",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="unban account",["help"]="Syntax: .unban account $Name\r\nUnban accounts for account name pattern.",["security"]=3,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNBAN_ACCOUNT"},{["name"]="unban character",["help"]="Syntax: .unban character $Name\r\nUnban accounts for character name pattern.",["security"]=3,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNBAN_CHARACTER"},{["name"]="unban ip",["help"]="Syntax : .unban ip $Ip\r\nUnban accounts for IP pattern.",["security"]=3,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNBAN_IP"},{["name"]="unban playeraccount",["help"]="Syntax: .unban playeraccount #name\nUnban accounts for character name pattern.",["security"]=3,["source"]="cs_ban.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNBAN_PLAYERACCOUNT"},{["name"]="unbindsight",["help"]="Syntax: .unbindsight\r\n\r\nRemoves bound vision. Cannot be used while currently possessing a target.",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNBINDSIGHT"},{["name"]="unfreeze",["help"]="Syntax: .unfreeze (#player)\r\n\"Unfreezes\" #player and enables his chat again. When using this without #name it will unfreeze your target.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNFREEZE"},{["name"]="unlearn",["help"]="Syntax: .unlearn #spell [all]\r\n\r\nUnlearn for selected player a spell #spell.  If 'all' provided then all ranks unlearned.",["security"]=2,["source"]="cs_learn.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNLEARN"},{["name"]="unmute",["help"]="Syntax: .unmute [$playerName]\r\n\r\nRestore chat messaging for any character from account of character $playerName (or selected). Character can be ofline.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNMUTE"},{["name"]="unpossess",["help"]="Syntax: .unpossess\r\n\r\nIf you are possessed, unpossesses yourself; otherwise unpossesses current possessed target.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNPOSSESS"},{["name"]="unstuck",["help"]="Syntax: .unstuck $playername [inn/graveyard/startzone]\n\nTeleports specified player to specified location. Default location is player's current hearth location.",["security"]=2,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_UNSTUCK"},{["name"]="wchange",["help"]="Syntax: .wchange #weathertype #grade\nSet current weather to #weathertype with an intensity of #grade.\n\n#weathertype can be 0 for fine, 1 for rain, 2 for snow, 3 for storm, 86 for thunders, 90 for blackrain.\n#grade is a float value from 0.0 (disabled) to 1.0 (maximum intensity).",["security"]=3,["source"]="cs_misc.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WCHANGE"},{["name"]="whispers",["help"]="Syntax: .whispers on|off\r\nEnable/disable accepting whispers by GM from players. By default use trinityd.conf setting.",["security"]=1,["source"]="cs_message.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_CAN_FILTER_WHISPERS"},{["name"]="worldstate scourgeinvasion battleswon",["help"]="Syntax: .worldstate scourgeinvasion battleswon <value>\nAdjusts the Scourge Invasion battles won count by <value> (can be negative).",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate scourgeinvasion show",["help"]="Syntax: .worldstate scourgeinvasion show\nDisplays the current status of the Scourge Invasion.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate scourgeinvasion startzone",["help"]="Syntax: .worldstate scourgeinvasion startzone <id>\nStarts a Scourge Invasion event in the zone specified by <id>.\nValid zone IDs: 0-7.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate scourgeinvasion state",["help"]="Syntax: .worldstate scourgeinvasion state <value>\nSets the Scourge Invasion state.\nValid values:\n0: Disabled\n1: Enabled",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate sunsreach counter",["help"]="Syntax: .worldstate sunsreach counter <index> <value>\n\nSets a Suns Reach worldstate counter and displays current Suns Reach status.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate sunsreach gate",["help"]="Syntax: .worldstate sunsreach gate <gate>.\nSets the phase of Sunwell Plateau Gate.\nValid values are:\n0: All Gates Closed\n1: Gate 1 Agamath Open\n2: Gate 2 Rohendar Open\n3: Gate 3 Archonisus Open.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate sunsreach gatecounter",["help"]="Syntax: .worldstate sunsreach gatecounter <index> <value>\n\nSets a Sunwell gate progression counter and displays current Suns Reach gate status.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate sunsreach phase",["help"]="Syntax: .worldstate sunsreach phase <value>.\nSets the phase of Sun's Reach.\nValid values are:\n0: Staging Area\n1: Sanctum\n2: Armory\n3: Harbor.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate sunsreach status",["help"]="Syntax: .worldstate sunsreach status\n\nDisplays current Suns Reach and Sunwell gate progression status.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="worldstate sunsreach subphase",["help"]="Syntax: .worldstate sunsreach subphase <mask>.\nSets the subphase mask of Sun's Reach.\nValid values are:\n1: Portal\n2: Anvil\n4: Alchemy Lab\n8: Monument\n15: All.",["security"]=3,["source"]="cs_worldstate.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG"},{["name"]="wp",["help"]="Syntax: wp $subcommand\n Type .wp to see a list of possible subcommands\n or .help wp $subcommand to see info on the subcommand.",["security"]=3,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="wp add",["help"]="Syntax: .wp add\r\n\r\nAdd a waypoint for the selected creature at your current position.",["security"]=3,["source"]="cs_wp.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WP_ADD"},{["name"]="wp event",["help"]="Syntax: .wp event $subcommand\nType .path event to see the list of possible subcommands or .help path event $subcommand to see info on subcommands.",["security"]=3,["source"]="cs_wp.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WP_EVENT"},{["name"]="wp load",["help"]="Syntax: .wp load $pathid\nLoad pathid number for selected creature. Creature must have no waypoint data.",["security"]=3,["source"]="cs_wp.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WP_LOAD"},{["name"]="wp modify",["help"]="Syntax: .wp modify\n\nModify the selected creature waypoint (path) data.",["security"]=3,["source"]="cs_wp.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WP_MODIFY"},{["name"]="wp reload",["help"]="Syntax: .wp reload $pathid\nLoad path changes ingame - IMPORTANT: must be applied first for new paths before .wp load #pathid ",["security"]=3,["source"]="cs_wp.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WP_RELOAD"},{["name"]="wp show",["help"]="Syntax: .wp show $option\nOptions:\non $pathid (or selected creature with loaded path) - Show path\noff - Hide path\ninfo $selected_waypoint - Show info for selected waypoint.",["security"]=3,["source"]="cs_wp.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WP_SHOW"},{["name"]="wp unload",["help"]="Syntax: .wp unload\nUnload path for selected creature.",["security"]=3,["source"]="cs_wp.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_WP_UNLOAD"},{["name"]="wpgps",["help"]="Syntax: .wpgps\r\nOutput current position to sql developer log as partial SQL query to be used in pathing (formated for waypoint_data table).\r\nUse .wpgps sai for waypoint (SAI) table format.",["security"]=3,["source"]="cs_debug.cpp",["dbOnly"]=false,["permission"]="rbac::RBAC_PERM_COMMAND_DEBUG_COSMETIC"},{["name"]="xp",["help"]="Syntax: .xp $subcommand\nType .help xp to see a list of subcommands\nor .help xp $subcommand to see info on the subcommand.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="xp default",["help"]="Syntax: .xp default\nSet your custom XP rate to the default value",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="xp disable",["help"]="Syntax: .xp disable\nDisable the custom XP rate.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="xp enable",["help"]="Syntax: .xp enable\nEnable the custom XP rate.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="xp set",["help"]="Syntax: .xp set $rate\nSet your custom XP rate.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""},{["name"]="xp view",["help"]="Syntax: .xp view\nView your current XP rate.",["security"]=0,["source"]="command table",["dbOnly"]=false,["permission"]=""}}
